/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+(w==='muckraker'?'muck-raker':w.toLowerCase().replaceAll(' ','-'))});
const P=(w,origin,c,m,qs)=>{const senseMap={mouse:[1,2,1,2],mouth:[1,2,3,1],move:[1,2,3,4],movie:[1,2,1,2],mow:[1,2,1,1],much:[1,2,3,1],muddy:[1,2,1,2],mug:[1,2,3,1],mule:[1,2,3,1],multinational:[1,2,1,2],multiple:[1,2,1,2],multitude:[1,2,1,2],mummy:[1,2,1,2],mundane:[1,2,1,2],mural:[1,2,1,2],murder:[1,2,3,1],murmur:[1,2,3,1],muscle:[1,2,3,1],muscular:[1,2,1,2],mushroom:[1,2,1,2],music:[1,2,1,2],must:[1,2,3,1],mustard:[1,2,1,2],mutate:[1,2,1,2],mutation:[1,2,1,2]};return D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(senseMap[w]?.[i]||1),type:'辨义与用法'}))});};
P('mourning','From Old English murnung, “grief or lamenting,” the verbal noun of mourn.',C('mourning.s1','哀悼','After her grandfather died, Lina wore a small black ribbon as a sign of mourning and took time away from work.','祖父去世后，莉娜佩戴一条黑色小缎带表示哀悼，并暂时离开工作休息。','After her grandfather died / Lina wore a small black ribbon / as a sign of mourning / and took time away from work.','mourning 作名词，指因亲友去世而产生或表达的悲伤。','黑色缎带和暂停工作都体现哀悼。'),M('The family held a celebration of mourning because everyone was delighted by the death and felt no sorrow.','The family observed a period of mourning after their relative died.','为逝者哀悼体现悲伤，不是庆祝死亡。'),[Q('Why did Lina wear the black ribbon?','To mark her mourning after her grandfather died.','To identify her as the funeral director.','To celebrate a new job.','mourning 指因死亡而表达的悲伤。'),Q('Mourning is most closely connected with?','grief after a death','a wedding reception','a public election','该词常指亲友去世后的哀悼。'),Q('What did Lina do besides wearing a ribbon?','She took time away from work.','She moved to a different country.','She wrote a new medical report.','例句还说她暂时离开工作。'),Q('Which phrase is natural?','a period of mourning','a mourning of to a period','mournings periodly','a period of mourning 是自然搭配。','collocation')]);
P('mouse','From Old English mus, from Proto-Germanic *mus; it names a small rodent and, by resemblance, a hand-operated computer pointer device.',[C('mouse.s1','小型啮齿动物','A field mouse slipped through a gap in the shed wall and disappeared beneath the feed sacks.','一只田鼠从棚屋墙缝钻进来，消失在饲料袋下面。','A field mouse slipped / through a gap in the shed wall / and disappeared / beneath the feed sacks.','mouse.s1 指一种体型小、长尾巴的啮齿动物。','例句描述动物从墙缝钻入并躲藏。'),C('mouse.s2','电脑指针设备','She connected a wireless mouse to the laptop so she could edit the map more precisely.','她把无线鼠标连接到笔记本电脑上，以便更精确地编辑地图。','She connected / a wireless mouse to the laptop / so she could edit the map / more precisely.','mouse.s2 指用手移动以控制屏幕指针的电脑设备。','无线设备用于控制电脑上的地图编辑。')],M('The biologist called the wireless pointer device a mouse, then described it as a living rodent that ran beneath the desk.','The biologist used “mouse” for the animal in the shed and for the computer pointer device in the lab.','动物和电脑设备是两个相关但不同的义项，不能把设备描述成活体啮齿动物。'),[Q('What did the field mouse do?','It slipped through a gap and hid beneath feed sacks.','It controlled the laptop pointer.','It edited the map wirelessly.','mouse.s1 指动物。'),Q('Why did she connect a wireless mouse?','To edit a map more precisely.','To feed a rodent in the shed.','To make the laptop heavier.','mouse.s2 指电脑指针设备。'),Q('Which sense is meant by “the mouse ate grain”?','The small rodent.','The computer device.','A map feature.','吃谷物的是动物义。'),Q('Which sense is meant by “click the mouse”?','The computer pointer device.','A field animal.','A shed wall gap.','click the mouse 指使用电脑设备。')]);
P('moustache','From French moustache, through Italian mostaccio, ultimately from Greek mustax, “upper lip”; it means the hair grown above the upper lip.',C('moustache.s1','面部毛发','The actor trimmed his moustache before the portrait session so the line above his lip looked neat.','肖像拍摄前，演员修剪了小胡子，让上唇上方的毛发边缘显得整齐。','The actor trimmed / his moustache / before the portrait session / so the line above his lip looked neat.','moustache 指男性或女性上唇上方生长的胡须。','演员修剪的是上唇上方的毛发。'),M('The costume note said to shave off the moustache, then asked the actor to keep all the hair above his lip.','The costume note asked the actor to shave off the moustache and leave his upper lip clean.','shave off 胡子意味着把上唇毛发剃掉，不能又要求保留。'),[Q('Where does a moustache grow?','Above the upper lip.','Along the jaw only.','Across the forehead.','moustache 指上唇上方的胡须。'),Q('What did the actor do before the portrait?','Trimmed his moustache.','Connected a wireless mouse.','Moved to another city.','例句明确说他修剪了小胡子。'),Q('Which phrase is natural?','grow a moustache','grow a moustache on the chin','moustache above a shoe','胡子长在上唇上方。','collocation'),Q('Which spelling is the common British form?','moustache','mustachee','moustash','moustache 是常见英式拼写。','spelling')]);
P('mouth','From Old English muþ, “oral opening”; the deeper Indo-European origin is disputed. The noun can name the oral opening or an entrance, and the verb can mean form words silently.',[C('mouth.s1','面部器官','The dentist asked the child to open her mouth wide so he could check the back teeth.','牙医让孩子张大嘴，好检查后槽牙。','The dentist asked the child / to open her mouth wide / so he could check / the back teeth.','mouth.s1 指用于进食和说话的口腔开口。','牙医检查的是孩子的口腔和牙齿。'),C('mouth.s2','入口河口','At the mouth of the cave, a narrow stream flowed out between two large stones.','在洞穴入口处，一股窄溪从两块大石头之间流出。','At the mouth of the cave / a narrow stream flowed out / between two large stones.','mouth.s2 可指河流、洞穴或容器的入口、出口或开口。','洞穴的开口是水流出的地方。'),C('mouth.s3','无声口型','Across the noisy room, Maya mouthed “thank you” to the volunteer without raising her voice.','在嘈杂的房间另一头，玛雅没有提高声音，只用口型对志愿者说“谢谢”。','Across the noisy room / Maya mouthed “thank you” / to the volunteer / without raising her voice.','mouth.s3 作动词，指只动嘴唇、不发声地说出词语。','她用口型表达，没有出声。')],M('Maya mouthed “thank you” by speaking loudly across the room so everyone could hear every word.','Maya mouthed “thank you” silently across the room.','大声说出话语并非无声地用口型表达。'),[Q('Why did the dentist ask the child to open her mouth?','To inspect her back teeth.','To enter the cave.','To make a silent sign.','mouth.s1 指口腔。'),Q('The mouth of a cave is its?','opening or entrance','deepest chamber','roof','mouth.s2 可指洞穴入口。'),Q('Maya mouthed “thank you” means she?','formed the words with her lips without sound','shouted the words across the room','wrote them on a card','mouth.s3 指无声地做出说话口型。'),Q('Which expression refers to spoken communication rather than writing?','by word of mouth','by mouth of the cave only','mouth the report aloud','word of mouth 指口头传播。','collocation')]);
P('mouthful','From mouth plus -ful, an amount that fills the mouth; it can also be a long or difficult word or phrase to say.',C('mouthful.s1','一口食物','He took a mouthful of soup, waited for it to cool, and then tasted it carefully.','他喝了一口汤，等它凉一些后仔细尝了尝。','He took / a mouthful of soup / waited for it to cool / and then tasted it carefully.','mouthful 指一口所能含下的量，常用于食物或饮料。','一口汤是mouthful的字面义。'),M('She swallowed a mouthful of soup by taking none into her mouth and drinking from an empty bowl.','She swallowed a mouthful of soup after letting it cool.','mouthful 指入口的一口，不能在完全没喝到时使用。'),[Q('What did he take a mouthful of?','Soup.','A mouse.','A telephone call.','mouthful 指一口，此处是一口汤。'),Q('A mouthful is usually?','an amount that fits in the mouth','a spoon too large to use','a whole meal for a family','该词表示一口或满嘴的量。'),Q('Why did he wait before tasting the soup?','It needed to cool.','It had to be moved forward.','The bowl was empty.','例句说他等汤凉一些再尝。'),Q('A name like “multidirectional municipal multimedia” may be called a mouthful because it is?','long or awkward to say','a small bite of food','a short greeting','mouthful 也可比喻难念或冗长的表达。')]);
P('mouthpiece','A compound of mouth and piece; it names the part of a device that goes at the mouth, or figuratively a person or group speaking for another.',[C('mouthpiece.s1','器具部件','The player replaced the cracked mouthpiece of her clarinet before the concert began.','音乐会开始前，演奏者更换了单簧管上裂开的吹口。','The player replaced / the cracked mouthpiece / of her clarinet / before the concert began.','mouthpiece.s1 指说话或吹奏时靠近嘴部的器具部件。','单簧管吹口是嘴部接触的部件。'),C('mouthpiece.s1','团体代言人','The newspaper was criticised as a mouthpiece for the party because it repeated its claims without independent scrutiny.','这家报纸因未经独立核查就重复该党的说法，被批评为该党的喉舌。','The newspaper was criticised / as a mouthpiece for the party / because it repeated its claims / without independent scrutiny.','mouthpiece.s2 比喻代表某团体发声的人或媒体，常带贬义。','报纸被认为替政党宣传。')],M('The article called the independent watchdog a mouthpiece for the party, although it repeatedly challenged the party’s statements.','The article called the newspaper a party mouthpiece because it repeated claims without checking them.','独立质疑某党的说法与充当其喉舌的指责不一致。'),[Q('What did the clarinet player replace?','The cracked part she blew into.','The entire concert hall.','A computer mouse.','mouthpiece.s1 指乐器的吹口部件。'),Q('The newspaper was called a mouthpiece because it?','repeated the party’s claims without independent checks','published independent investigations that challenged the party','printed only musical scores','mouthpiece.s2 指替团体发声的媒体。'),Q('Which object has a mouthpiece?','A clarinet.','A window curtain.','A city council building.','单簧管有吹口部件。'),Q('Which phrase fits the figurative sense?','a mouthpiece for the organisation','a mouthpiece inside a mouse','mouthpiece of to the organisation','常说 a mouthpiece for a group。','collocation')]);
P('movable','From move plus -able; it means able to be moved or not fixed in one place.',C('movable.s1','可移动家具','The gallery used movable partitions so staff could rearrange the exhibition space for each new collection.','画廊使用可移动隔板，以便员工为每批新藏品重新布置展区。','The gallery used / movable partitions / so staff could rearrange / the exhibition space for each new collection.','movable 作形容词，表示能够被移动或不固定。','隔板可以移动以改变空间布局。'),M('The display was called movable although its frame had been welded into the concrete floor and could not shift.','The display was movable because staff could wheel it into a different room.','焊死在地面且无法移动的展架不是 movable。'),[Q('Why did the gallery choose movable partitions?','They could rearrange the exhibition space.','They prevented any change to the layout.','They served as a musical instrument.','movable 指可移动的。'),Q('A movable object is?','able to be moved','permanently fixed','too large to exist','movable 意为能够移动。'),Q('Which item is movable?','A wheeled display screen.','A wall built into the foundation.','A fixed stone pillar.','带轮展屏可移动。'),Q('Movable is formed from move plus?','-able','-hood','-ish','-able 表示“能够……的”。','word-formation')]);
P('move','From Old French moveir and Latin movere, “to move”; as a verb it can mean change position, relocate, affect emotionally, formally propose, or take an action or turn.',[C('move.s1','改变位置','Please move the ladder away from the doorway so people can leave the hall safely.','请把梯子从门口挪开，让人们能够安全离开大厅。','Please move the ladder / away from the doorway / so people can leave / the hall safely.','move.s1 指改变位置或使某物移动。','梯子被移离门口。'),C('move.s2','搬迁居住','The family moved to Bristol after the parents found jobs near the university.','父母在大学附近找到工作后，这家人搬到了布里斯托尔。','The family moved to Bristol / after the parents found jobs / near the university.','move.s2 不及物用法表示搬家、迁往另一地点生活或工作。','一家人改变居住城市。'),C('move.s3','情感打动','The documentary moved the audience because it showed how the volunteers reunited separated families.','这部纪录片展现志愿者如何让失散家庭团聚，深深打动了观众。','The documentary moved the audience / because it showed / how the volunteers reunited / separated families.','move.s3 作及物动词表示使人产生强烈情感。','团聚故事让观众感动。'),C('move.s4','正式提议','At the committee meeting, Priya moved that the library extend its weekend opening hours.','委员会会议上，普里娅正式提议延长图书馆周末开放时间。','At the committee meeting / Priya moved / that the library extend / its weekend opening hours.','move.s4 在会议中可表示正式提出建议或动议。','她在委员会提出延长开放时间的动议。'),C('move.s5','一步行动','His next move in the chess game forced the opponent to protect the queen.','他在棋局中的下一步迫使对手保护皇后。','His next move in the chess game / forced the opponent / to protect the queen.','move.s5 作名词可指一步棋或为达成目标采取的行动。','下一步棋改变了对局策略。')],M('The family moved to Bristol by staying in the same house and refusing to relocate anywhere.','The family moved to Bristol after accepting jobs there.','没有改变居住地点就不是搬迁。'),[Q('What should happen to the ladder?','It should be shifted away from the doorway.','It should block the doorway.','It should be turned into a chess piece.','move.s1 指移动物体。'),Q('The family moved to Bristol means they?','changed where they lived','were emotionally touched','proposed a new library rule','move.s2 表示搬迁。'),Q('The documentary moved the audience means it?','made them feel strong emotion','changed their home address','formally proposed a motion','move.s3 表示打动观众。'),Q('Priya moved that the library extend hours means she?','formally proposed the change at the meeting','carried the library building away','felt sad about chess','move.s4 指正式提出动议。')]);
P('move forward','A phrasal verb from move plus forward; it means to advance physically or to make progress with a plan or process.',C('move forward.s1','推进工作','Once the safety review was complete, the project team could move forward with construction.','安全审查完成后，项目团队得以继续推进施工。','Once the safety review was complete / the project team could move forward / with construction.','move forward 可指向前移动，也常比喻继续推进计划或工作。','审查完成使项目可以继续。'),M('The project moved forward by being permanently cancelled before any review or construction began.','The project moved forward after the review approved the safety plan.','项目取消而未开展不是推进。'),[Q('What allowed construction to move forward?','The completed safety review.','A permanent cancellation.','A missing mouthpiece.','move forward 表示项目继续推进。'),Q('To move forward physically means to?','advance ahead','remain in exactly the same place','move backwards only','字面义是向前移动。'),Q('Which phrase is natural?','move forward with a proposal','move forward at a proposal with of','forward move proposal to with','常见结构为 move forward with a plan/proposal。','collocation'),Q('The project moved forward means it?','made progress','was abandoned permanently','became a movie theater','短语常比喻工作取得进展。')]);
P('movement','From move plus -ment; it names the act of changing position, or a group of people organised around a shared aim.',[C('movement.s1','身体移动','The therapist measured the movement of the patient’s shoulder before and after each exercise.','治疗师在每次练习前后测量患者肩部的活动幅度。','The therapist measured / the movement of the patient’s shoulder / before and after / each exercise.','movement.s1 指移动或改变位置的过程。','治疗师观察肩部活动。'),C('movement.s1','社会团体','The environmental movement organised a town-hall meeting to campaign for cleaner public transport.','环保运动组织了一场市民大会，倡议改善公共交通的清洁程度。','The environmental movement organised / a town-hall meeting / to campaign / for cleaner public transport.','movement.s1 也可指为共同目标组织起来的社会团体。','环保人士围绕共同目标组织行动。')],M('The therapist recorded no movement because the patient’s shoulder changed position freely through its full range.','The therapist recorded movement when the patient raised the shoulder during the exercise.','关节完全没有移动与活动幅度正常矛盾。'),[Q('What did the therapist measure?','The patient’s shoulder motion.','The size of the town hall.','The number of movie screens.','movement 可指身体移动。'),Q('The environmental movement is?','a group organised around a shared cause','one person’s shoulder exercise','a film shown in a cinema','movement 也指社会运动或团体。'),Q('Why did the group hold a town-hall meeting?','To campaign for cleaner public transport.','To measure a shoulder.','To announce a new moustache style.','该组织围绕环保目标开展活动。'),Q('Movement is formed from move plus?','-ment','-ous','-able','movement 是 move 加名词后缀 -ment。','word-formation')]);
P('movie','From moving picture, shortened to movie; it can mean a film or, in the phrase the movies, the film industry.',[C('movie.s1','电影作品','We watched a documentary movie about the restoration of an old railway station.','我们看了一部关于修复旧火车站的纪录片。','We watched / a documentary movie / about the restoration / of an old railway station.','movie.s1 指在影院或屏幕上放映的电影。','纪录片是电影作品。'),C('movie.s2','电影行业','She hopes to work in the movies, designing costumes for large historical productions.','她希望进入电影业，为大型历史题材作品设计服装。','She hopes to work / in the movies / designing costumes / for large historical productions.','the movies 可指电影制作和放映行业。','她想在电影行业从事服装设计。')],M('She worked in the movies as a costume designer, but the article said this meant she had never entered the film industry.','She worked in the movies as a costume designer for historical productions.','the movies 在该短语中指电影行业。'),[Q('What did they watch?','A documentary film about a railway station.','A live football match at the station.','A lecture about a computer mouse.','movie.s1 指电影作品。'),Q('She hopes to work in the movies means she wants to work in?','the film industry','a railway museum only','a city council office','movie.s2 指电影行业。'),Q('What kind of movie did they watch?','A documentary.','A musical instrument.','A weather report.','例句明确是一部纪录片。'),Q('Which phrase refers to the film business?','work in the movies','watch a movie tonight','a movie poster','the movies 可指电影行业。','usage')]);
P('movie theater','A compound of movie and theater; it names a building where films are shown to the public.',C('movie theater.s1','影院场所','The movie theater added an afternoon screening so families could see the new film before dinner.','电影院增加了一场下午放映，让家庭观众能在晚饭前看新片。','The movie theater added / an afternoon screening / so families could see the new film / before dinner.','movie theater 指向公众放映电影的建筑或场所。','影院安排了电影放映场次。'),M('The town’s movie theater had no screen or film showings and was used only to sell groceries.','The town’s movie theater screened films for local audiences.','没有银幕或放映活动的杂货店不是电影院。'),[Q('What did the movie theater add?','An afternoon film screening.','A new railway platform.','A musicology course.','movie theater 是电影放映场所。'),Q('Where do audiences go to watch a film publicly?','A movie theater.','A mudflat.','A mouthpiece.','电影院面向公众放映电影。'),Q('Why was an afternoon screening useful?','Families could watch before dinner.','It moved the film to another country.','It replaced the theatre with a clinic.','加场时间方便家庭观众。'),Q('Movie theater is a compound of movie and?','theater','movement','murder','该词由 movie 与 theater 组成。','word-formation')]);
P('moving','Present participle of move, used as an adjective for something that causes strong emotion, especially pity or sympathy.',C('moving.s1','感人故事','The moving account of a nurse caring for displaced children left several readers in tears.','这篇护士照料流离失所儿童的感人叙述让几位读者落泪。','The moving account / of a nurse caring for displaced children / left several readers / in tears.','moving.s1 作形容词，表示令人感动，常使人产生怜悯或同情。','读者落泪说明叙述触动了情感。'),M('The article was moving because it caused every reader to feel nothing and forget the children immediately.','The article was moving because its account of the nurse’s care brought readers to tears.','令人落泪的故事并非毫无情感影响。'),[Q('Why was the account moving?','It described a nurse caring for displaced children.','It listed train platforms without a story.','It showed a computer pointer.','moving 指令人感动的。'),Q('What reaction did some readers have?','They were brought to tears.','They moved to another country.','They repaired the movie theater.','例句显示读者受故事触动。'),Q('A moving speech is likely to?','make listeners feel strong emotion','change a person’s address','describe a movable chair','moving 描写打动人的内容。'),Q('Moving is the -ing form of?','move','mow','muddle','moving 来自动词 move。','word-formation')]);
P('mow','From Old English māwan, “cut grass or grain”; it means to cut grass, usually with a machine or scythe, and can also mean knock down people in large numbers.',[C('mow.s1','修剪草地','I mow the lawn every Saturday in summer, leaving the wildflowers untouched along the fence.','夏天我每周六修剪草坪，同时保留围栏边的野花。','I mow the lawn / every Saturday in summer / leaving the wildflowers / untouched along the fence.','mow.s1 指用割草机或镰刀把草割短。','修剪草坪但留下野花。'),C('mow.s2','大量扫倒','The novel describes how machine-gun fire mowed down the advancing soldiers, a scene of mass violence.','小说描写机枪火力扫倒了前进的士兵，这是大规模暴力场面。','The novel describes / how machine-gun fire mowed down the advancing soldiers / a scene / of mass violence.','mow.s2 在书面表达中可指大量杀死或击倒。','该短语描述大规模暴力，不是普通修草义。')],M('The gardener mowed the lawn by leaving every blade of grass at its original height.','The gardener mowed the lawn with a mower, cutting the grass short.','草一根未割短就不算修剪草坪。'),[Q('What does the gardener do each Saturday?','Cuts the lawn while leaving wildflowers.','Moves the lawn into the house.','Plants a new fence.','mow.s1 指割草修剪。'),Q('In the novel, “mowed down” describes?','soldiers being killed or knocked down in large numbers','a lawn being watered carefully','people moving forward peacefully','mow.s2 描述大规模扫倒或杀伤。'),Q('What does “mow the lawn” mean?','Cut the grass short.','Water the flowers.','Build a fence.','mow the lawn 是割草坪。','collocation'),Q('The simple past of mow is?','mowed','mowen','mowned','mow 的过去式是 mowed，过去分词可用 mown。','verb-form')]);
P('mr','An abbreviation of Mister, the title placed before a man’s name or surname.',C('mr.s1','姓名前称谓','Mr Lewis will chair the meeting and introduce the new members of the board.','刘易斯先生将主持会议，并介绍董事会新成员。','Mr Lewis will chair the meeting / and introduce / the new members / of the board.','Mr 是 Mister 的缩写，书写时通常后接男性姓名或姓氏。','称谓放在姓名前。'),M('The invitation addressed him as “Lewis Mr,” placing Mr after his surname.','The invitation addressed him as “Mr Lewis,” placing the title before his surname.','Mr 应置于姓名前，而不是姓氏后。'),[Q('Who will chair the meeting?','Mr Lewis.','Ms Lewis’s mouse.','The board’s movie theater.','Mr Lewis 是姓名前称谓。'),Q('Mr is short for?','Mister','movement','murder','Mr 是 Mister 的缩写。','word-formation'),Q('Where does Mr normally appear?','Before a man’s name or surname.','After the surname.','At the end of every sentence.','该称谓通常置于男性姓名前。'),Q('Which punctuation is standard in “Mr Lewis”?','The abbreviation is followed by the surname.','The surname must come first.','Mr must be written after the full stop in every case.','常见顺序是 Mr + 姓氏。','grammar')]);
P('ms','A modern title written Ms, used before a woman’s name without indicating whether she is married.',C('ms.s1','中性女性称谓','Ms Carter asked the hotel to update her booking but did not state her marital status.','卡特女士请酒店更新预订，但没有说明自己的婚姻状况。','Ms Carter asked the hotel / to update her booking / but did not state / her marital status.','Ms 是女性姓名前的称谓，不透露或强调婚姻状况。','预订信息中只使用中性称谓。'),M('The form required her to replace Ms with Mrs because Ms always means that a woman is unmarried.','The form allowed her to use Ms because the title does not indicate marital status.','Ms 不说明婚姻状况，不等于未婚称谓。'),[Q('What does Ms Carter’s title tell the hotel about her marriage?','Nothing; Ms does not indicate marital status.','It proves she is married.','It proves she is unmarried.','Ms 是不表明婚姻状况的女性称谓。'),Q('Where is Ms placed?','Before a woman’s name.','After the surname.','Only as a plural noun.','称谓置于姓名前。'),Q('Which title is neutral about marital status?','Ms','Mrs only','Miss only','Ms 不指明婚姻状况。'),Q('Which sentence uses Ms correctly?','Ms Carter updated her booking.','Carter Ms updated her booking.','Ms updated Carter her booking.','Ms 放在姓名前。','grammar')]);
P('much','From Old English micel, “great or large”; it is used with uncountable nouns for a large amount, as an adverb for degree, and as a pronoun for a large amount.',[C('much.s1','不可数数量','There was not much water left in the tank after the overnight leak.','水箱整夜漏水后，里面剩下的水不多了。','There was not much water / left in the tank / after the overnight leak.','much.s1 常修饰不可数名词，表示大量或多少。','water 是不可数名词。'),C('much.s2','程度副词','The revised route is much shorter than the one the delivery driver used yesterday.','修改后的路线比送货司机昨天走的路线短得多。','The revised route is much shorter / than the one / the delivery driver used yesterday.','much.s2 作副词可加强程度，尤其修饰比较级。','much 修饰 shorter。'),C('much.s3','代词用法','Much of the evidence was preserved, but the original photographs were lost in the fire.','大部分证据得以保存，但原始照片在火灾中遗失。','Much of the evidence was preserved / but the original photographs / were lost / in the fire.','much.s3 可单独作代词，表示大量或大部分。','Much of + 不可数名词指其中的大部分。')],M('There were much individual bottles left in the box, and each one could be counted.','There were many individual bottles left in the box.','可数复数名词 bottles 通常用 many，不用 much。','countability'),[Q('How much water remained after the leak?','Not much.','Many bottles exactly.','A few countable drops only as a plural noun.','much.s1 修饰不可数名词 water。'),Q('“Much shorter” means?','A great deal shorter.','Only slightly shorter.','Much is a noun meaning a route.','much.s2 加强比较级程度。'),Q('“Much of the evidence” refers to?','A large amount of the evidence.','Many separate pieces counted individually only.','The missing photographs only.','much.s3 作代词表示大量或大部分。'),Q('Which sentence is correct?','How much water is left?','How much bottles are left?','How many water is left?','water 不可数，搭配 much。','countability')]);
P('muckraker','From muck-rake, a tool for scraping filth; muckraker was extended from one who rakes muck to a journalist who exposes corruption and scandal.',C('muckraker.s1','揭露腐败','The muckraker spent months tracing public contracts and published evidence that officials had steered them to friends.','这名黑幕揭发记者花了数月追查公共合同，并公布官员将合同偏向熟人的证据。','The muckraker spent months / tracing public contracts / and published evidence / that officials had steered them to friends.','muckraker 指揭露政治或商业腐败的记者或调查写作者。','文章通过证据揭露了权力滥用。'),M('The editor called the reporter a muckraker because she hid the corruption and printed only flattering praise of officials.','The editor called the reporter a muckraker because she uncovered evidence of officials’ corruption.','掩盖腐败而非揭露腐败，与黑幕揭发者的含义相反。'),[Q('What did the muckraker investigate?','Public contracts steered toward officials’ friends.','A mouse in the newsroom.','The weather at a movie theater.','muckraker 指调查并揭露腐败的写作者。'),Q('Why did the reporter publish the evidence?','To expose officials’ wrongdoing.','To conceal the contracts.','To advertise a new mustard brand.','其工作是揭露不当行为。'),Q('Muckraker originally referred to?','Someone who raked muck or filth.','A person who controlled a computer mouse.','A worker who harvested mulberries.','词源字面与清理污物的耙子有关。','word-formation'),Q('Which modern use is accurate?','An investigative writer exposing corruption.','A reporter who refuses to investigate any claims.','A person who repairs farm machinery only.','现代义是揭黑幕的调查记者。')]);
P('mucous','From Latin mucosus, “slimy or mucous,” from mucus; the adjective means containing or resembling mucus.',C('mucous.s1','生理组织','The doctor explained that the mucous membrane protects the inside of the nose and helps trap dust.','医生解释说，黏膜保护鼻腔内侧，并帮助拦截灰尘。','The doctor explained / that the mucous membrane protects the inside of the nose / and helps trap dust.','mucous 是形容词，描述含有黏液或与黏膜有关的组织。','mucous 修饰 membrane，指鼻腔黏膜。'),M('The textbook labelled the dry outer bone tissue mucous because it contained no mucus and formed no membrane.','The textbook described the moist lining of the nose as a mucous membrane.','干燥骨组织既无黏液也不是黏膜。'),[Q('What does a mucous membrane do in the nose?','It protects the lining and helps trap dust.','It forms the hard outer skeleton.','It controls a computer pointer.','mucous membrane 指有黏液的保护性内膜。'),Q('Mucous means?','containing or resembling mucus','made entirely of bone','free of all moisture','mucous 描述含黏液或黏液状。'),Q('Which spelling is the adjective?','mucous','mucus','mukus','mucous 是形容词，mucus 是名词。','word-formation'),Q('Which phrase is standard?','mucous membrane','mucus membrane as the adjective form','mucously membrane','mucous 作形容词修饰 membrane。','grammar')]);
P('mud','From Middle Low German mudde or Middle Dutch modde, “thick mud,” with the deeper root uncertain; it means wet, soft earth.',C('mud.s1','雨后泥泞','After the storm, the farm track was covered in mud, and the tractor left deep ruts as it crossed the field.','暴雨过后，农场小路满是泥，拖拉机穿过田地时留下深深的车辙。','After the storm / the farm track was covered in mud / and the tractor left deep ruts / as it crossed the field.','mud 指雨水或水分混入土壤后形成的湿软泥土。','雨后小路和车辙体现泥泞地面。'),M('The path was covered in mud although it was dry, clean, and free from any soft earth.','The path was covered in mud after rain softened the soil.','干燥洁净且没有湿软泥土时不应说 covered in mud。'),[Q('Why did the tractor leave deep ruts?','The track was muddy after a storm.','The field was paved with stone.','The tractor flew above the ground.','雨后湿软的泥土留下车辙。'),Q('Mud is?','wet, soft earth','a dry polished metal','a type of film','mud 指湿软的土。'),Q('Which phrase is natural?','covered in mud','covered by muds as plural','mud on the machine to by','常说 covered in mud。','collocation'),Q('What happened to the farm track after the storm?','It became muddy.','It was converted into a movie theater.','It became a mucous membrane.','暴雨后小路满是泥。')]);
P('muddle','Possibly related to mud; as a verb it means to confuse someone or make an issue unclear, or to mix things in a disorganised way.',C('muddle.s1','思路混乱','The rushed instructions muddled the volunteers, who then delivered the medical boxes to the wrong entrance.','匆忙的说明把志愿者弄糊涂了，他们随后把医疗箱送到了错误入口。','The rushed instructions muddled the volunteers / who then delivered the medical boxes / to the wrong entrance.','muddle 作动词，指使人困惑或把事情弄得混乱。','说明不清导致志愿者送错地点。'),M('The instructions muddled nobody because every step was clear and the volunteers delivered each box correctly.','The instructions muddled the volunteers, who misunderstood where the boxes belonged.','完全清楚且每件物品都送对，与造成混乱相反。'),[Q('What did the rushed instructions do?','They confused the volunteers.','They made the boxes lighter.','They opened the correct entrance.','muddle 指使人糊涂或困惑。'),Q('Where did the volunteers take the boxes?','To the wrong entrance.','To the correct clinic storage room.','To a movie theater.','说明混乱导致送错入口。'),Q('To muddle an explanation is to?','make it unclear or confusing','make it precise and easy to follow','translate it perfectly','muddle 可指把事情弄得不清楚。'),Q('Which phrase is natural?','muddle the facts','muddle to the facts about','muddledly facts the','muddle 可直接接被弄乱的对象。','grammar')]);
P('muddy','From mud plus -y; it means covered with mud or, figuratively, unclear and confused; as a verb it can mean cover with mud or make less clear.',[C('muddy.s1','泥泞道路','The muddy lane became slippery after the storm, so the school bus stopped at the main road.','暴雨后泥泞小路变得湿滑，校车因此停在主路上。','The muddy lane became slippery / after the storm / so the school bus / stopped at the main road.','muddy.s1 作形容词，表示沾满泥或含泥浑浊。','雨后道路泥泞湿滑。'),C('muddy.s2','模糊争议','The spokesperson’s vague answer muddied the issue by avoiding the question about missing funds.','发言人含糊其辞，回避了资金去向问题，使事情更加不清楚。','The spokesperson’s vague answer muddied the issue / by avoiding the question / about missing funds.','muddy.s2 作动词可比喻使问题、事实或含义更混乱。','回避关键问题使争议更模糊。')],M('The spokesperson muddied the facts by presenting a complete, transparent account that resolved every question.','The spokesperson muddied the facts by omitting key details about the funds.','清楚透明地解决疑问不会使事实更混乱。'),[Q('Why did the bus stop at the main road?','The muddy lane had become slippery.','The road was freshly paved and dry.','The bus had turned into a movie theater.','muddy.s1 表示泥泞、湿滑。'),Q('How did the spokesperson muddy the issue?','By avoiding the question about missing funds.','By publishing a full accounting.','By repairing the road.','muddy.s2 比喻使事实不清楚。'),Q('Which sense is used in “muddy boots”?','Covered with mud.','Confused about an issue.','A shoe with no back.','muddy.s1 指鞋上沾泥。'),Q('Which sense is used in “muddy the debate”?','Make the discussion less clear.','Cover the debate with soil.','Move the debate to a lane.','muddy 可作动词表示使讨论混乱。')]);
P('mudflats','Compound of mud and flat; it refers to broad, low, muddy shores exposed at low tide, often used by feeding birds.',C('mudflats.s1','潮间滩涂','At low tide, thousands of wading birds fed across the mudflats before the returning water covered them.','退潮时，成千上万只涉禽在泥滩上觅食，涨潮后海水又将滩涂淹没。','At low tide / thousands of wading birds fed / across the mudflats / before the returning water covered them.','mudflats 是退潮时露出的低平泥质海岸地带。','滩涂随潮汐露出并成为鸟类觅食处。'),M('At high tide the mudflats remained dry and fully exposed, while the sea had withdrawn far offshore.','At low tide, the mudflats were exposed for birds to feed on.','退潮时滩涂露出；高潮通常会将其淹没。'),[Q('When were the mudflats exposed?','At low tide.','Only during a snowstorm.','At the top of a mountain.','mudflats 在退潮时露出。'),Q('What fed on the mudflats?','Wading birds.','A school of indoor fish.','Movie audiences.','许多涉禽在泥滩觅食。'),Q('A mudflat is a?','low muddy shore exposed by the tide','deep underground cave','paved urban road','mudflat 指潮间泥滩。'),Q('Why did the returning water cover them?','The tide came in.','The birds built a bridge.','The mud turned into stone.','涨潮时水位上升并淹没滩涂。')]);
P('mudstone','A compound of mud and stone; it names a fine-grained sedimentary rock formed mainly from compacted mud, silt, and clay.',C('mudstone.s1','沉积岩类','The geologist split the mudstone sample and found fine layers of clay and silt inside.','地质学家劈开泥岩样本，发现内部有细密的黏土和粉砂层。','The geologist split / the mudstone sample / and found fine layers / of clay and silt inside.','mudstone 是主要由压实泥、粉砂和黏土形成的细粒沉积岩。','样本中细粒沉积物形成层理。'),M('The field guide identified the loose wet soil as mudstone even though it had never hardened into rock.','The field guide identified the hardened fine-grained sedimentary rock as mudstone.','未固结的湿土不是岩石。'),[Q('What did the geologist find inside the mudstone?','Fine layers of clay and silt.','A living mouse.','A metal movie screen.','mudstone 中有细粒沉积物层。'),Q('Mudstone is a type of?','sedimentary rock','mammal','musical instrument','泥岩属于沉积岩。'),Q('How does mudstone form?','Fine sediment compacts and hardens.','A tree grows berries.','A wetland becomes a theater.','泥、粉砂和黏土压实成岩。'),Q('Which word is closest to mudstone’s material?','clay-rich rock','soft fresh water','dry paper','mudstone 是细粒、含黏土的岩石。')]);
P('muffled','Past participle of muffle, from a verb meaning cover or wrap; it describes a sound made quiet or hard to hear.',C('muffled.s1','隔物声音','A muffled alarm sounded from inside the locked cupboard, so the caretaker searched for the hidden device.','上锁的柜子里传出闷闷的警报声，管理员便寻找藏起来的设备。','A muffled alarm sounded / from inside the locked cupboard / so the caretaker / searched for the hidden device.','muffled 作形容词，表示声音被遮住、变小或不清晰。','柜门隔住声音，使警报难以听清。'),M('The alarm was muffled although it rang at full volume in the open hall and could be heard across town.','The alarm sounded muffled because the cupboard door blocked much of its noise.','开放大厅里音量很大且全城可闻，不符合声音被遮掩。'),[Q('Why was the alarm muffled?','The locked cupboard blocked much of its sound.','It was broadcast at maximum volume outdoors.','It had been replaced by a silent light.','muffled 指声音不清晰、被遮挡。'),Q('A muffled voice is difficult to?','hear clearly','see through','move forward','muffled 描写听起来闷、不清楚的声音。'),Q('Which object might muffle a sound?','A thick closed door.','A loudspeaker turned up fully.','A clear glass of water','厚门能挡住声音。'),Q('Muffled is the past participle of?','muffle','muddle','muster','muffled 来自动词 muffle。','word-formation')]);
P('mug','The drinking vessel is of uncertain origin, perhaps Scandinavian; a separate slang use means a person’s face, and the verb can mean rob someone in public.',[C('mug.s1','带柄杯子','He poured tea into a ceramic mug and carried it carefully to the desk.','他把茶倒进陶瓷马克杯，小心地端到桌边。','He poured tea / into a ceramic mug / and carried it carefully / to the desk.','mug.s1 指常带把手、用于饮水的高直身杯。','陶瓷杯用于盛茶。'),C('mug.s2','俚语面孔','The newspaper printed the suspect’s mug on the front page, using the slang word for his face or photograph.','报纸把嫌疑人的脸部照片刊在头版，这里用的是表示脸或肖像的俚语义。','The newspaper printed / the suspect’s mug / on the front page / using the slang word for his face or photograph.','mug.s2 是俚语，指人的脸，尤见于 mug shot。','报纸刊出警方登记照。'),C('mug.s3','街头抢劫','The tourist was mugged near the station when a thief threatened him and stole his wallet.','游客在车站附近遭人持威胁抢劫，钱包被偷。','The tourist was mugged / near the station / when a thief threatened him / and stole his wallet.','mug.s3 作动词，指在公共场所袭击并抢劫某人。','陌生人威胁游客并夺走钱包。')],M('The tourist was mugged when a shopkeeper served him tea in a ceramic cup.','The tourist was mugged when a thief threatened him and stole his wallet.','用杯子给人上茶不是街头抢劫。'),[Q('What did he carry to the desk?','A ceramic drinking cup.','A police photograph.','A stolen wallet.','mug.s1 指带柄杯子。'),Q('The newspaper printed the suspect’s mug means it printed?','a picture of his face','a ceramic cup he owned','a map of the station','mug.s2 是脸或肖像的俚语。'),Q('The tourist was mugged means he was?','attacked and robbed in public','served tea in a cup','asked to move his luggage','mug.s3 指当街袭击抢劫。'),Q('Which use of mug is slang for “face”?','His mug appeared in the photograph.','She filled a mug with tea.','A thief mugged the tourist.','此处 mug 作脸或面孔的俚语。')]);
P('muggy','From obsolete mug meaning “drizzling mist,” plus -y; it describes unpleasant warm, humid weather.',C('muggy.s1','闷热天气','The air felt muggy before the storm, and the runners stopped to drink water in the shade.','暴雨前空气闷热潮湿，跑步者停下来在阴凉处喝水。','The air felt muggy / before the storm / and the runners stopped / to drink water in the shade.','muggy 作形容词，描述令人不舒服的温暖潮湿天气。','闷热环境使跑步者停下补水。'),M('The afternoon was muggy because the air was cold, dry, and comfortable.','The afternoon was muggy because warm damp air made it uncomfortable.','冷而干燥的空气不符合 muggy。'),[Q('What was the weather like before the storm?','Warm and unpleasantly humid.','Cold and completely dry.','Snowy and windy.','muggy 表示闷热潮湿。'),Q('Why did runners stop?','They needed water and shade in the muggy air.','They wanted to repair a mug.','The storm had already ended.','闷热环境下跑者停下休息喝水。'),Q('Muggy is closest to?','hot and humid','icy and dry','bright but freezing','muggy 描写湿热天气。'),Q('Which setting is most likely muggy?','A warm, damp evening before rain.','A crisp, dry winter morning.','A refrigerated room','温暖潮湿、雨前的空气很闷热。')]);
P('mulberry','From Middle English morberie, influenced by Latin morum “mulberry” plus berry; it names a Morus tree, its fruit, or a dark reddish-purple colour.',C('mulberry.s1','桑树果实','The children gathered ripe mulberries from the tree and stained their fingers dark purple.','孩子们从树上摘熟透的桑葚，手指都被染成深紫色。','The children gathered / ripe mulberries from the tree / and stained their fingers / dark purple.','mulberry 可指桑树、桑葚果实，也可指深紫红色。','果实和染色体现其植物及颜色义。'),M('The children picked mulberries from a pine tree, whose cones produced bright yellow citrus fruit.','The children picked mulberries from the mulberry tree and stained their hands purple.','松树不结桑葚或柑橘类果实。'),[Q('What did the children gather?','Ripe fruit from a mulberry tree.','Pine cones from a forest.','A bowl of mustard.','mulberry 指桑树或其果实。'),Q('What colour stained their fingers?','Dark purple.','Bright blue.','Pale green.','桑葚汁把手指染成深紫色。'),Q('Mulberry may name?','the tree, its berry, or a dark reddish-purple colour','only a kind of animal','a legal title','mulberry 有树、果实和颜色义。'),Q('Which phrase is natural?','a mulberry stain','a mulberry of shoe','mulberryly fruit tree','桑葚汁可留下 mulberry-coloured stain。','collocation')]);
P('mule','From Latin mulus, “mule”; besides the hybrid animal, it can mean a stubborn person or a backless shoe.',[C('mule.s1','杂交家畜','The mule carried water and tools up the rocky path, where a larger vehicle could not pass.','骡子沿着大车无法通行的岩石小路驮水和工具上山。','The mule carried water and tools / up the rocky path / where a larger vehicle / could not pass.','mule.s1 指公驴与母马杂交所生的家畜。','骡子在崎岖道路上驮运物品。'),C('mule.s2','固执之人','Even after seeing the new measurements, he remained a mule and refused to reconsider his estimate.','即使看到了新的测量数据，他仍像头倔骡子一样拒绝重新考虑估算。','Even after seeing the new measurements / he remained a mule / and refused / to reconsider his estimate.','mule.s2 可非正式比喻固执不听劝的人。','此处比喻顽固坚持错误估算。'),C('mule.s3','无后跟鞋','She slipped on a leather mule before stepping out to water the plants on the balcony.','她套上一只皮质无后跟拖鞋，走到阳台给植物浇水。','She slipped on / a leather mule / before stepping out / to water the plants on the balcony.','mule.s3 可指后跟敞开的拖鞋或鞋款。','鞋后跟敞开，便于套穿。')],M('The pack animal was called a mule, but the entry described it as a purebred horse with no donkey ancestry.','The pack animal was a mule, the offspring of a male donkey and a female horse.','骡子是驴与马的杂交后代，不是纯种马。'),[Q('Why could the mule use the rocky path?','A larger vehicle could not pass there.','The path was a wide motorway.','The animal had no load to carry.','mule.s1 指驮运家畜。'),Q('Calling him a mule means he was?','stubborn','a backless shoe','a male donkey','mule.s2 比喻顽固之人。'),Q('What did she wear on the balcony?','A backless shoe.','A leather saddle.','A wool mitten.','mule.s3 指无后跟鞋。'),Q('A mule animal is commonly a cross between?','a male donkey and a female horse','a male horse and a female sheep','two kinds of mouse','骡子是公驴与母马杂交后代。')]);
P('mulish','From mule plus -ish; it means stubborn and unwilling to cooperate, like a mule.',C('mulish.s1','固执态度','Despite three careful explanations, the mulish witness refused to correct a date that the records clearly disproved.','尽管别人仔细解释了三遍，这名固执的证人仍拒绝更正一个已被记录明确推翻的日期。','Despite three careful explanations / the mulish witness refused to correct a date / that the records / clearly disproved.','mulish 作形容词，表示像骡子一样倔强、不愿配合。','证人坚持明显错误的日期。'),M('The negotiator was mulish because she quickly reconsidered her view whenever new evidence appeared.','The negotiator was mulish because she refused to reconsider even after evidence disproved her claim.','愿意根据证据改变看法不属于顽固不化。'),[Q('Why was the witness mulish?','He refused to correct a disproved date.','He changed his view after checking the records.','He carried supplies up a hill.','mulish 表示顽固、不肯配合。'),Q('Mulish is closest to?','stubborn','flexible','muffled','mulish 与 stubborn 接近。'),Q('Which suffix helps form mulish?','-ish','-ment','-able','mulish 由 mule 加 -ish 构成。','word-formation'),Q('A mulish response is likely to?','resist reasonable advice','accept every correction immediately','show a moving film','顽固的人会抗拒合理建议。')]);
P('multi-faceted','A compound of multi- “many” and faceted, “having faces or aspects”; it means having several distinct sides or features.',C('multi-faceted.s1','复杂议题','The multi-faceted housing problem involves rents, transport, local jobs, and access to schools.','住房问题有多个方面，涉及租金、交通、本地就业和入学机会。','The multi-faceted housing problem / involves rents, transport, local jobs, / and access to schools.','multi-faceted 作形容词，描述由多个不同方面构成的复杂事物。','列出的因素显示问题不止一个方面。'),M('The report called the issue multi-faceted although it involved exactly one simple factor and no related concerns.','The report called the issue multi-faceted because rent, transport, and employment all affected it.','只有单一因素的问题不宜称为多方面的。'),[Q('Why is the housing issue multi-faceted?','It involves several connected concerns.','It has only one simple cause.','It is a type of movie.','multi-faceted 指具有多个方面。'),Q('Which concern is mentioned in the example?','Access to schools.','A clarinet mouthpiece.','A mouse in a cupboard.','例句列出入学机会等因素。'),Q('Multi- contributes the meaning?','many','before','against','multi- 表示多个、多种。','word-formation'),Q('Which spelling is also a standard variant?','multifaceted','multifacettedness','multifacetful','multi-faceted 与 multifaceted 都是常见拼写变体。','spelling')]);
P('multicellular','Formed from multi- “many” and cellular, from cell; it describes an organism made of many cells, often with specialised roles.',C('multicellular.s1','生物结构','A multicellular fungus has many cells that cooperate in growth and reproduction.','多细胞真菌由许多细胞组成，这些细胞协同完成生长和繁殖。','A multicellular fungus has many cells / that cooperate / in growth and reproduction.','multicellular 描述由多个细胞构成的生物。','真菌由多个细胞协同组成。'),M('The lab called a single-celled bacterium multicellular even though it consisted of just one cell.','The lab described the larger organism as multicellular because it consisted of many cells.','只有一个细胞的细菌不是多细胞生物。'),[Q('A multicellular organism is made of?','Many cells.','One cell only.','No living cells.','multicellular 表示由多个细胞组成。'),Q('What do the fungus’s cells do?','Cooperate in growth and reproduction.','Operate separate movie theaters.','Turn into mudstone.','细胞协同完成生长与繁殖。'),Q('Which word part means “many”?','multi-','micro-','mis-','multi- 表示多。','word-formation'),Q('Which organism is multicellular?','An animal made of many cells.','A single isolated cell.','A printed diagram only.','多细胞动物由许多细胞组成。')]);
P('multicultural','Formed from multi- “many” and cultural; it describes a society, group, or policy containing several cultural traditions.',C('multicultural.s1','多元社区','The multicultural neighbourhood holds a spring festival where residents share food, music, and stories from many traditions.','这个多元文化社区举办春季节庆，居民分享不同传统的食物、音乐和故事。','The multicultural neighbourhood holds a spring festival / where residents share food, music, and stories / from many traditions.','multicultural 描述包含多种文化传统的社会或群体。','居民共同呈现不同文化传统。'),M('The organiser called the event multicultural although it excluded every tradition except one and barred other communities.','The organiser described the neighbourhood as multicultural because many cultural groups shared its festival.','排斥所有其他文化不符合多元文化的含义。'),[Q('What makes the neighbourhood multicultural?','Residents share traditions from many cultures.','Everyone follows one identical custom only.','It contains several movie screens.','multicultural 指包含多种文化传统。'),Q('What did residents share at the festival?','Food, music, and stories.','Only a city budget.','A single legal contract.','节庆活动分享多种文化内容。'),Q('Which prefix means “many”?','multi-','mono-','mis-','multi- 表示多个。','word-formation'),Q('Which setting is multicultural?','A school where students bring traditions from many communities.','A club that admits only one cultural group.','A single-family kitchen','多社区学生共同学习体现多元文化。')]);
P('multidirectional','Formed from multi- “many” and directional; it means moving or operating in several directions.',C('multidirectional.s1','多向信号','The multidirectional antenna receives signals from several points around the building without being turned by hand.','这款多向天线无需手动转动，就能接收建筑周围多个方向的信号。','The multidirectional antenna receives signals / from several points around the building / without being turned / by hand.','multidirectional 描述能朝多个方向移动、作用或接收信号。','天线可接收来自不同方向的信号。'),M('The antenna was multidirectional although it could receive signals only from one fixed direction.','The antenna was multidirectional because it received signals from several sides of the building.','只能朝单一方向工作不符合多向的含义。'),[Q('What can the multidirectional antenna receive?','Signals from several directions.','Only one fixed signal from behind a wall.','A bowl of mulberries.','multidirectional 指作用方向不止一个。'),Q('Does the antenna need to be turned by hand?','No.','Yes, every second.','It cannot receive any signal.','例句说明它无需手动转动。'),Q('Multi- contributes which idea?','Several or many.','One only.','Wrongly.','multi- 表示多个。','word-formation'),Q('Which device is multidirectional?','A sensor that detects motion from different sides.','A lamp fixed to point only north.','A single-direction speaker','多向传感器能从多个方向检测。')]);
P('multifaceted','From multi- “many” and facet, “one side of a many-sided object”; it means having many aspects, skills, or points of view.',C('multifaceted.s1','多方面人才','The multifaceted curator combines conservation expertise with public teaching, historical research, and exhibition design.','这位多才多面的策展人兼具文物保护、公众教学、历史研究和展览设计能力。','The multifaceted curator combines / conservation expertise / with public teaching, historical research, / and exhibition design.','multifaceted 描写具有多个不同方面、技能或特征的事物。','策展人拥有多个专业角色。'),M('The profile called the curator multifaceted even though it listed one narrow skill and no other responsibilities.','The profile called the curator multifaceted because she worked across conservation, teaching, and research.','只有单一技能不足以体现多方面。'),[Q('Why is the curator multifaceted?','She works across several professional areas.','She has only one simple task.','She is a type of antenna.','multifaceted 指具有多个方面。'),Q('Which skill is mentioned?','Exhibition design.','Repairing a mouse.','Mowing a public lawn.','策展人负责展览设计等多项工作。'),Q('What is a facet?','One aspect or side of something.','A type of wet soil.','A legal title.','facet 指方面或侧面。','word-formation'),Q('Multifaceted and multi-faceted are?','spelling variants with the same general meaning','opposites','different parts of speech by rule','两种拼写都表示多方面的。','spelling')]);
P('multifunctional','Formed from multi- “many,” function, and -al; it describes equipment designed to perform several different functions.',C('multifunctional.s1','多功能设备','The multifunctional printer can scan receipts, copy forms, and send documents securely by email.','这台多功能打印机可以扫描收据、复印表格并安全地通过电子邮件发送文件。','The multifunctional printer can / scan receipts, copy forms, / and send documents securely / by email.','multifunctional 描述一件设备或产品可以实现多个功能。','打印机还具备扫描、复印和发送等用途。'),M('The brochure called the printer multifunctional although it could only print and had no other features.','The brochure called the device multifunctional because it printed, scanned, copied, and emailed documents.','只有打印一种功能的设备不是多功能设备。'),[Q('Which functions does the printer perform?','Scanning, copying, and emailing documents.','Mowing the lawn and watering trees.','Receiving radio signals only.','例句列出多种功能。'),Q('A multifunctional tool is designed for?','Several different uses.','One use only.','No practical use.','multifunctional 指多功能的。'),Q('Which part means “many”?','multi-','-al','-tion','multi- 表示多种。','word-formation'),Q('Which object is multifunctional?','A phone that takes photos, maps routes, and makes calls.','A spoon used only for stirring tea.','A fixed stone wall','具有多种用途的手机是多功能设备。')]);
P('multilateral','From multi- “many” and lateral, “side”; it describes an agreement or action involving three or more parties.',C('multilateral.s1','多方谈判','A multilateral treaty was signed by five coastal nations to coordinate rescue operations at sea.','五个沿海国家签署了多边条约，以协调海上救援行动。','A multilateral treaty was signed / by five coastal nations / to coordinate / rescue operations at sea.','multilateral 描述涉及三方或更多方面的协议、行动或关系。','五国共同签署，属于多边安排。'),M('The report called a contract between exactly two firms multilateral, though no other party participated.','The report called the agreement multilateral because five governments signed it.','只有两个参与方通常是双边而非多边。'),[Q('How many nations signed the treaty?','Five.','Exactly two.','One.','multilateral 指三方或更多方参与。'),Q('What did the treaty coordinate?','Sea rescue operations.','Movie schedules.','Mucous membranes.','条约旨在协调海上救援。'),Q('A multilateral agreement involves?','three or more parties','one party only','exactly two parties only','multi- 表示多个方面。','word-formation'),Q('Which is multilateral?','A climate pact signed by six countries.','A private promise between two friends.','A solo performance','六国共同签署的协议涉及多方。')]);
P('multimedia','From multi- “many” and media, plural of medium; it describes communication or content combining several forms such as text, sound, images, and video.',C('multimedia.s1','多媒体学习','The museum’s multimedia guide combines recorded narration, archival photographs, maps, and short video clips.','博物馆的多媒体导览结合了录音讲解、档案照片、地图和短视频。','The museum’s multimedia guide combines / recorded narration, archival photographs, maps, / and short video clips.','multimedia 指结合多种传播媒介或内容形式。','导览同时使用声音、照片、地图和视频。'),M('The guide was described as multimedia although it contained only one printed sentence and no sound or images.','The guide was multimedia because it combined narration, photographs, maps, and video.','只有一行文字并不算结合多种媒体。'),[Q('What does the museum guide combine?','Narration, photographs, maps, and video.','Only a printed street name.','A mug and a mulberry tree.','multimedia 指结合多种内容形式。'),Q('Multimedia communication may combine?','Text, sound, images, and video.','Only one spoken sentence.','Only a paper receipt.','多媒体可以融合文字、声音、图像等。'),Q('Multi- means?','many','one','opposite','multi- 表示多种。','word-formation'),Q('Which product is multimedia?','An app with text, audio, maps, and clips.','A plain unillustrated note.','A single still label','该应用结合了多种媒介。')]);
P('multinational','Formed from multi- “many” and national; as an adjective it concerns several countries, and as a noun it can mean a large company operating in several countries.',[C('multinational.s1','跨国合作','A multinational research team shared ocean data from laboratories in Japan, Kenya, and Canada.','一个跨国研究团队分享了来自日本、肯尼亚和加拿大实验室的海洋数据。','A multinational research team / shared ocean data / from laboratories / in Japan, Kenya, and Canada.','multinational.s1 作形容词，表示涉及多个国家。','研究团队成员和实验室跨越多个国家。'),C('multinational.s2','跨国公司','The multinational opened a new factory abroad while keeping its headquarters and design studio at home.','这家跨国公司在海外开设新工厂，同时把总部和设计工作室留在本国。','The multinational opened a new factory abroad / while keeping its headquarters / and design studio / at home.','multinational.s2 作名词，指在多个国家经营的大型公司。','公司在本国和海外均有业务。')],M('The article called a shop operating only in one small town a multinational, although it had no activity abroad.','The article called the company a multinational because it operated factories in several countries.','只在一个小镇经营的商店不是跨国公司。'),[Q('Why was the research team multinational?','Its laboratories were in three different countries.','All researchers lived on one street.','It studied many types of mud.','multinational.s1 指涉及多国。'),Q('What did the multinational open abroad?','A factory.','A movie theater in its home town only.','A private school for one family.','multinational.s2 指跨国经营的大型公司。'),Q('A multinational company operates in?','more than one country','exactly one village','no physical or online location','multinational 指经营范围跨越多国。'),Q('Which prefix contributes “many”?','multi-','mis-','mono-','multi- 表示多个国家或对象。','word-formation')]);
P('multiple','From Latin multiplex, “having many folds,” from multi- “many” and -plex “folded”; as an adjective it means many or involving several parts, and as a noun it can mean an exact multiple of a number.',[C('multiple.s1','多个零件','The repair required multiple replacement parts, including two bolts, a seal, and a new filter.','这次维修需要多个替换零件，包括两颗螺栓、一个密封圈和一个新滤芯。','The repair required / multiple replacement parts / including two bolts, a seal, / and a new filter.','multiple.s1 作形容词，表示多个或由多部分构成。','例句列出多种替换零件。'),C('multiple.s2','数学倍数','Twenty-four is a multiple of six because six divides into it exactly four times.','24是6的倍数，因为6可以整除24，结果是4。','Twenty-four is / a multiple of six / because six divides into it / exactly four times.','multiple.s2 作名词，指一个数被另一个数整除后得到的整数倍数。','24=6×4。')],M('The technician ordered multiple parts but received just one item and no other component.','The technician ordered multiple parts: bolts, a seal, and a filter.','单独一件并非多个零件。'),[Q('How many kinds of replacement part are mentioned?','Several, including bolts, a seal, and a filter.','Exactly one part only.','No parts were needed.','multiple.s1 表示多个。'),Q('Why is twenty-four a multiple of six?','Six divides it exactly four times.','Twenty-four cannot be divided by six.','It is smaller than six.','multiple.s2 是整数倍数。'),Q('Which expression uses multiple as an adjective?','multiple appointments','a multiple of six','multiply by six','multiple appointments 表示多个预约。','grammar'),Q('Which expression uses multiple as a noun?','Thirty is a multiple of five.','There are multiple options.','They multiply five by six.','a multiple of five 中 multiple 是名词。','grammar')]);
P('multiplication','From Latin multiplicatio, from multiplicare, “to multiply”; it names the arithmetic operation of multiplying and the process of increasing in number.',C('multiplication.s1','算术运算','The class checked the multiplication by dividing the product by one of the original factors.','全班通过用积除以一个原因数来核对乘法运算。','The class checked the multiplication / by dividing the product / by one of the original factors.','multiplication 指乘法运算或乘数相乘的过程。','用积除以因数可以核对乘积。'),M('The student checked the multiplication by adding the two factors and ignoring the product.','The student checked the multiplication by confirming that six times seven equals forty-two.','加法不能直接验证此处的乘法结果。'),[Q('How did the class check the multiplication?','They divided the product by a factor.','They measured the desk in millimetres.','They counted the movie screens.','multiplication 指乘法运算。'),Q('What is 6 × 7?','42','13','76','乘法事实为六乘七等于四十二。'),Q('Which operation is multiplication?','Repeated addition of equal groups.','Subtraction of a number from itself.','A type of movement.','multiplication 是乘法。'),Q('Multiplication is related to which verb?','multiply','murmur','mow','multiplication 与 multiply 同源。','word-formation')]);
P('multiplicative','From multiply plus -ative; it describes a process in which quantities combine by multiplication or grow by a factor.',C('multiplicative.s1','复利增长','The model uses a multiplicative growth rate, so each year’s increase is calculated from the new total rather than the original amount alone.','该模型采用乘法式增长率，因此每年的增量按新的总额计算，而不只按最初金额计算。','The model uses / a multiplicative growth rate / so each year’s increase / is calculated from the new total.','multiplicative 描述以乘法或倍数方式运作的关系。','每年基于更新后的总额计算增长，体现乘数效应。'),M('The analyst called the process multiplicative although it added the same fixed amount each year and never used a factor.','The analyst called the process multiplicative because the amount grew by the same percentage each year.','固定加上同一数额是加法式增长，而不是乘法式增长。'),[Q('Why is the model’s growth multiplicative?','Each year’s increase is based on the updated total.','It adds the same fixed number regardless of the total.','It divides every amount by zero.','multiplicative 指乘数式增长。'),Q('A multiplicative increase often grows by?','a factor or percentage','the same fixed number only','a change of spelling','乘法式增长通常按比例或倍数变化。'),Q('Which word is the base for multiplicative?','multiply','murder','muddle','multiplicative 来自 multiply 的词族。','word-formation'),Q('Which process is multiplicative?','A balance that grows by 5% of its current value each year.','A balance that gains exactly £5 each year.','A value that stays fixed','按当前值增长百分比属于乘法式变化。')]);
P('multiplicity','From Latin multiplicitas, from multiplex, “having many parts”; it means a great number or the condition of having many aspects.',C('multiplicity.s1','多种因素','The multiplicity of causes behind the outage made it difficult for engineers to identify one quick fix.','停电背后原因众多，工程师很难找到一个快速解决办法。','The multiplicity of causes / behind the outage / made it difficult / for engineers to identify one quick fix.','multiplicity 指数量众多或多重性。','停电原因不止一个。'),M('The report described a multiplicity of causes even though it identified only one possible cause.','The report described a multiplicity of causes, including equipment failure, flooding, and operator error.','只有一个因素不能称为众多原因。'),[Q('Why was the outage hard to fix quickly?','It had many possible causes.','It had no cause at all.','It was a movie theater.','multiplicity 指数量众多。'),Q('A multiplicity of options means?','a great many options','exactly one option','no available options','a multiplicity 表示许多。'),Q('Which word family is multiplicity related to?','multiple','mucous','moustache','multiplicity 与 multiple 同源相关。','word-formation'),Q('Which phrase is natural?','the multiplicity of factors','the multiplicity factorsly','multiplicity to many factor','常说 the multiplicity of factors。','collocation')]);
P('multiply','From Latin multiplicare, “increase many times”; it means perform multiplication or increase greatly in number.',C('multiply.s1','乘法计算','Multiply the number of seats in each row by the number of rows to estimate the hall’s total capacity.','将每排座位数乘以排数，即可估算大厅的总容量。','Multiply the number of seats in each row / by the number of rows / to estimate / the hall’s total capacity.','multiply 可指数学乘法，也可表示数量迅速增加。','座位行数相乘得到总容量。'),M('To find the total seats, the planner multiplied the number of rows by zero and expected a positive total.','The planner multiplied the seats per row by the number of rows to calculate the total.','乘以零会得到零，无法得出正的座位总数。'),[Q('How should the planner estimate total seats?','Multiply seats per row by the number of rows.','Add the hall’s wall height to the roof.','Divide by the number of movie screens.','multiply 表示相乘。'),Q('If bacteria multiply rapidly, they?','increase in number quickly','become less numerous','turn into furniture','multiply 也可表示快速增多。'),Q('Which preposition follows multiply in the calculation?','by','with of','at from','数学表达为 multiply A by B。','collocation'),Q('What does 8 multiplied by 3 equal?','24','11','5','八乘三等于二十四。')]);
P('multipurpose','Formed from multi- “many” and purpose; it describes an object or place suitable for several different uses.',C('multipurpose.s1','多用途场地','The multipurpose room serves as a classroom during the day and a community meeting hall in the evening.','这间多功能室白天用作教室，晚上则作为社区会议厅。','The multipurpose room serves / as a classroom during the day / and a community meeting hall / in the evening.','multipurpose 指为多种用途设计或适用的。','房间白天和晚上承担不同用途。'),M('The council called the room multipurpose although it was permanently sealed and could serve no activity.','The council called the room multipurpose because it hosted classes and community meetings.','不能用于任何活动的房间并非多用途。'),[Q('What two uses does the room have?','Classroom and meeting hall.','Museum and movie theater only.','Kitchen and garage only.','该房间白天教学、晚上开会。'),Q('A multipurpose tool is?','suitable for several uses','designed for only one task','unable to perform any task','multipurpose 表示多用途的。'),Q('Which prefix means “many”?','multi-','mono-','mis-','multi- 表示多。','word-formation'),Q('Which item is multipurpose?','A folding table used for meals and workshops.','A sealed box that cannot be opened.','A single-use ticket','折叠桌可用于用餐和活动。')]);
P('multistage','Formed from multi- “many” and stage; it describes a process, device, or event with several stages.',C('multistage.s1','分阶段流程','The multistage selection process begins with an application, followed by a written task and two interviews.','多阶段选拔流程先提交申请，然后完成笔试任务并参加两轮面试。','The multistage selection process begins / with an application / followed by a written task / and two interviews.','multistage 描述分成多个阶段完成的过程或装置。','申请、笔试和面试构成多个阶段。'),M('The selection was called multistage although every applicant completed just one brief step.','The selection was multistage because candidates passed through an application, a task, and interviews.','仅有一个步骤的流程不是多阶段。'),[Q('Which stages are part of the selection?','Application, written task, and interviews.','Only a lottery draw.','A single medical test.','流程包含多个步骤。'),Q('A multistage plan has?','several stages','one stage only','no planned steps','multi- 表示多个阶段。'),Q('Which prefix means “many”?','multi-','sub-','mis-','multi- 表示多个。','word-formation'),Q('Which event is multistage?','A race with qualifying rounds, semifinals, and a final.','A single coin toss.','An unplanned pause','多轮比赛由多个阶段组成。')]);
P('multistory','US spelling formed from multi- “many” and story in the building sense; it describes a building with several floors.',C('multistory.s1','多层楼房','The multistory car park has six levels, with a ramp connecting each floor to the street entrance.','这座多层停车楼有六层，每层通过坡道连接到街道入口。','The multistory car park has six levels / with a ramp connecting each floor / to the street entrance.','multistory 描述有多层楼面的建筑；英式拼法常见 multi-storey。','停车楼有六层。'),M('The building was described as multistory even though it had only one ground-floor room and no upper level.','The building was multistory, with six floors connected by ramps.','只有一层的建筑不是多层楼。'),[Q('How many levels does the car park have?','Six.','One.','None.','multistory 指多层建筑。'),Q('What connects the floors?','A ramp.','A river mouth.','A clarinet mouthpiece.','坡道连接各层。'),Q('What is a common British spelling variant?','multi-storey','multistories','multi-storyed','英式英语常写 multi-storey。','spelling'),Q('Which building is multistory?','A hotel with several floors.','A single-storey garden shed.','An open field','多层酒店符合该词义。')]);
P('multitude','From Latin multitudo, from multus, “many”; it means a very large number, or a large crowd of people.',[C('multitude.s1','数量众多','A multitude of small decisions shaped the final design, from the window spacing to the colour of the handles.','许多细小决定共同塑造了最终设计，从窗户间距到把手颜色都有考虑。','A multitude of small decisions / shaped the final design / from the window spacing / to the colour of the handles.','multitude.s1 指数量极多。','设计由许多细节决定。'),C('multitude.s2','人群聚集','A multitude gathered outside the station to welcome the returning athletes.','大批人群聚集在车站外，欢迎归来的运动员。','A multitude gathered / outside the station / to welcome / the returning athletes.','multitude.s2 可指人数众多的人群。','人们聚集在车站欢迎运动员。')],M('A multitude of people gathered outside, although only one person attended the event.','A multitude gathered outside the station, with hundreds of supporters welcoming the athletes.','一人出席不能称为众多人群。'),[Q('What shaped the final design?','Many small decisions.','A single colour choice only.','One missing floor.','multitude.s1 指许多因素或事项。'),Q('Who gathered outside the station?','A large crowd welcoming athletes.','One empty bus.','A team of museum curators only.','multitude.s2 指人数众多的人群。'),Q('A multitude of details means?','a very large number of details','exactly two details','no details','multitude 表示大量。'),Q('Which phrase is standard?','a multitude of choices','a multitude choicesly','multitudes of one choice only','常说 a multitude of + 名词。','collocation')]);
P('multivolume','Formed from multi- “many” and volume, “a book”; it describes a work published in more than one bound volume.',C('multivolume.s1','多卷书籍','The library catalogues the multivolume history as one work spread across eight separately bound books.','图书馆把这部多卷本历史著作编为一项作品，共分八册装订。','The library catalogues / the multivolume history / as one work / spread across eight separately bound books.','multivolume 描述由多册装订书卷组成的一套作品。','一部著作分成八卷。'),M('The library called a single thin booklet multivolume even though it had only one bound volume.','The library catalogued the eight-book history as a multivolume work.','单册小册子不属于多卷本。'),[Q('How many books made up the multivolume history?','Eight.','One thin booklet.','A thousand loose pages with no binding.','multivolume 指一部作品分成多卷。'),Q('A multivolume reference work is?','published in several bound books','printed on one page only','a movie with several scenes','该词描述多册出版物。'),Q('Which prefix means “many”?','multi-','mono-','muc-','multi- 表示多个。','word-formation'),Q('Which item is multivolume?','An encyclopedia issued in ten books.','A single pocket dictionary.','A one-page poster','十册百科全书是多卷本。')]);
P('mum','A familiar British word for mother, from the child-language reduplication of ma- found widely across languages.',C('mum.s1','家庭称呼','When the school play ended, the child ran backstage and asked his mum to take a photograph.','学校演出结束后，孩子跑到后台请妈妈给他拍张照片。','When the school play ended / the child ran backstage / and asked his mum / to take a photograph.','mum 是英式英语中常见的“妈妈”称呼，语气亲切。','孩子对母亲使用家庭称呼。'),M('The child called his male teacher mum and asked him to take a photograph of the play.','The child asked his mum, his mother, to take a photograph after the play.','mum 指母亲，不是男性老师。'),[Q('Who did the child ask to take a photograph?','His mother.','His math textbook.','A movie critic.','mum 是“妈妈”。'),Q('Mum is especially common in?','British English','only formal legal writing','computer programming','mum 是常见英式家庭称呼。'),Q('Which phrase is natural?','ask your mum for help','ask mum of help to','mum your help ask for','ask your mum for help 是自然表达。','collocation'),Q('What kind of word is mum?','a familiar family term','a legal offence','a weather adjective','mum 是亲切的家庭称呼。')]);
P('mumble','Probably a frequentative of mum, an imitative closed-mouth sound; it means to speak or eat indistinctly and quietly.',C('mumble.s1','含糊低语','He mumbled his answer with his eyes on the floor, so the interviewer asked him to speak more clearly.','他低头含糊地回答，面试官便请他再说清楚一些。','He mumbled his answer / with his eyes on the floor / so the interviewer asked him / to speak more clearly.','mumble 指含混、低声地说话，常因发音不清而难以听懂。','面试官要求他重复清楚，说明回答含糊。'),M('The witness mumbled every word loudly and distinctly so the court reporter could hear perfectly.','The witness mumbled the answer so quietly that the court reporter asked for it again.','大声清晰表达不属于 mumble。'),[Q('Why did the interviewer ask him to speak again?','He mumbled his answer indistinctly.','He shouted too loudly.','He changed the meeting room.','mumble 指含糊低声说话。'),Q('A person who mumbles is difficult to?','hear or understand clearly','see from far away','move between rooms','mumble 的话常难以听清。'),Q('What did the man do while answering?','Looked at the floor.','Trimmed his moustache.','Mowed the lawn.','例句说他低头回答。'),Q('Which verb is closest to mumble?','mutter indistinctly','announce clearly','sing loudly','mutter indistinctly 与 mumble 接近。')]);
P('mummy','The preserved-body word came through Medieval Latin mumia from Arabic/Persian terms connected with bitumen; the British child’s word for mother is a separate form related to mammy.',[C('mummy.s1','古代遗体','The museum’s Egyptian mummy remained wrapped in linen while conservators monitored the case’s humidity.','博物馆里的埃及木乃伊仍以亚麻布包裹，文物修复人员持续监控展柜湿度。','The museum’s Egyptian mummy remained / wrapped in linen / while conservators monitored / the case’s humidity.','mummy.s1 指经过防腐和干燥处理、常以布包裹的遗体。','埃及遗体被亚麻布包裹并在博物馆保存。'),C('mummy.s2','英式亲昵称呼','“Mummy, can you read this story again?” the child asked as she climbed into bed.','孩子爬上床时问：“妈妈，你能再给我读一遍这个故事吗？”','“Mummy / can you read this story again?” / the child asked / as she climbed into bed.','mummy.s2 是英国儿童对母亲的亲昵称呼。','孩子在睡前称呼母亲为 Mummy。')],M('The museum label called the linen-wrapped ancient body a mummy, then said it was a living child asking for a story.','The museum label described the wrapped ancient body as a mummy, distinct from a child’s use of “Mummy” for mother.','古代防腐遗体与儿童对母亲的称呼是不同义项。'),[Q('What was kept in the museum case?','An ancient wrapped body.','A living child’s bedtime story.','A multivolume encyclopedia.','mummy.s1 指防腐保存的遗体。'),Q('Who does the child call Mummy?','Her mother.','The museum conservator.','An Egyptian statue only.','mummy.s2 是儿童对母亲的称呼。'),Q('Why did conservators monitor the case?','To protect the preserved body.','To help the child fall asleep.','To improve a movie theater screen.','展柜环境有助于保护遗体。'),Q('The preserved-body word mummy came through a term connected with?','bitumen or asphalt','a musical scale','a computer pointer','该词经相关语汇传入，与沥青材料有关。','word-formation')]);
P('munch','Probably imitative in origin; it means to chew or eat noisily, often with enjoyment.',C('munch.s1','咀嚼零食','The hikers munched apples at the rest stop while they checked the route for the next stage.','徒步者在休息点一边嚼苹果，一边查看下一段路线。','The hikers munched apples / at the rest stop / while they checked the route / for the next stage.','munch 作动词，指用力或发出声音地咀嚼食物。','他们停下吃苹果补充体力。'),M('The child munched the crisp apple silently without moving her jaw or taking a bite.','The child munched a crisp apple noisily during the break.','没有咀嚼或咬食就不是 munch。'),[Q('What did the hikers munch?','Apples.','A wooden map.','A movie ticket.','munch 指咀嚼食物，例句中是苹果。'),Q('When did they eat?','At a rest stop.','While climbing the final cliff.','After the festival ended a week later.','徒步者在休息点吃东西。'),Q('To munch something is to?','chew it, often noisily','swallow it without eating','measure it in millimetres','munch 表示咀嚼。'),Q('Which phrase is natural?','munch on an apple','munch at an apple to','munch by an apple for','munch on something 是常见搭配。','collocation')]);
P('mundane','From Old French mondain and Late Latin mundanus, “of this world”; a later English sense describes something ordinary and dull.',[C('mundane.s1','日常琐事','After months of crisis work, she spent a quiet afternoon on mundane tasks such as sorting receipts and watering plants.','经历数月危机工作后，她用一个安静的下午处理整理收据、浇花等日常琐事。','After months of crisis work / she spent a quiet afternoon / on mundane tasks / such as sorting receipts and watering plants.','mundane.s1 指普通、平常且可能乏味的事情。','整理收据和浇花是平常的日常事务。'),C('mundane.s2','世俗现世','The philosopher distinguished spiritual questions from mundane concerns such as food, shelter, and work.','哲学家把精神问题与食物、住所、工作等世俗事务区分开来。','The philosopher distinguished spiritual questions / from mundane concerns / such as food, shelter, / and work.','mundane.s2 指尘世的、与精神或宗教事务相对的现实生活方面。','食物、住所和工作属于现世事务。')],M('She called sorting routine receipts mundane because it was an extraordinary spiritual revelation unrelated to daily life.','She called sorting routine receipts mundane because it was ordinary daily work.','普通整理事务并非超自然启示。'),[Q('What mundane tasks did she do?','Sort receipts and water plants.','Travel to another planet.','Lead a religious procession.','mundane.s1 指平常琐事。'),Q('Mundane concerns in the philosopher’s contrast include?','Food, shelter, and work.','Only spiritual questions.','A multistory car park.','mundane.s2 指世俗现实事务。'),Q('A mundane routine is usually?','ordinary and possibly dull','extraordinary and supernatural','made of many cells','mundane 可表示平凡乏味。'),Q('Mundane originally described things?','of this world','inside a computer','related to a wall','mundanus 与尘世、世界相关。','word-formation')]);
P('municipal','From Latin municipalis, “of a self-governing town,” from municipium; it means related to a town or city government.',C('municipal.s1','市政服务','The municipal water department repaired the broken main and notified residents before restoring service.','市政供水部门修好了破裂的主管道，并在恢复供水前通知居民。','The municipal water department repaired / the broken main / and notified residents / before restoring service.','municipal 作形容词，表示与城镇或市政府有关。','供水部门负责市政基础设施。'),M('The council described the private family’s kitchen as municipal although it was not owned or run by the city.','The council described the city-run water service as municipal.','私人厨房与市政府没有关系。'),[Q('Who repaired the water main?','The municipal water department.','A visiting movie critic.','A private school pupil.','municipal 指市政部门的。'),Q('Municipal services are connected with?','local city or town government','the national film industry only','a person’s mouth','municipal 与地方市镇政府有关。'),Q('Which facility is municipal?','A city-operated library.','A privately owned bedroom.','A wild mulberry tree','市政府运营的图书馆属于市政设施。'),Q('Municipal comes from Latin relating to?','a self-governing town','mucus','mowing grass','municipalis 指城镇自治事务。','word-formation')]);
P('municipality','From Latin municipium, “self-governing town,” through municipal; it means a town or city with local government, or its governing body.',C('municipality.s1','地方自治机构','The municipality voted to replace the old bridge and set aside funds for construction next year.','该市镇自治机构投票决定更换旧桥，并为明年施工拨出资金。','The municipality voted / to replace the old bridge / and set aside funds / for construction next year.','municipality 可指有自治政府的市镇，也可指其市政管理机构。','机构作出本地基础设施决策。'),M('The report called a temporary private club a municipality although it had no town, residents, or local government.','The report called the self-governing town a municipality.','没有城镇居民或地方政府的私人俱乐部不是 municipality。'),[Q('What did the municipality vote to do?','Replace the old bridge.','Build a museum about mummies.','Close all local government offices.','municipality 指作出地方决策的市镇或政府机构。'),Q('A municipality generally has?','local self-government','no residents or civic authority','only a movie screen','municipality 是有地方治理的城镇。'),Q('Which decision might a municipality make?','Repairing a local road.','Changing a person’s surname.','Moving the moon','地方道路维修属于市镇管理事务。'),Q('Municipality is related to which adjective?','municipal','mucous','muscular','municipality 与 municipal 同源。','word-formation')]);
P('munificent','From Latin munificus, “generous,” built from munus, “gift or service,” and facere, “to make”; it means extremely generous, especially with gifts or money.',C('munificent.s1','慷慨捐赠','A munificent donor funded the library’s new reading room and gave the school a separate grant for books.','一位慷慨的捐赠者资助了图书馆的新阅览室，还另拨款为学校购书。','A munificent donor funded / the library’s new reading room / and gave the school / a separate grant for books.','munificent 形容给予大量慷慨支持的人或礼物。','捐赠者资助场所并另赠购书款。'),M('The review called the donor munificent even though she gave nothing and refused every request for help.','The review called the donor munificent because she provided substantial gifts to the library and school.','完全没有给予或捐助，不符合慷慨的描述。'),[Q('What did the munificent donor provide?','Funding for a reading room and books.','A bill for unpaid rent.','A single used pencil only.','munificent 指非常慷慨。'),Q('A munificent gift is?','generous and substantial','tiny and grudging','unrelated to giving','该词强调慷慨丰厚。'),Q('Munificent is connected with Latin munus, meaning?','gift or service','wall','fog','munus 有礼物、服务的意思。','word-formation'),Q('Which person is munificent?','Someone who makes a substantial donation.','Someone who refuses all reasonable giving.','Someone who counts a mouse’s whiskers','大量捐助体现慷慨。')]);
P('mural','From Latin muralis, “of a wall,” from murus, “wall”; as a noun it is a large wall painting, and as an adjective it means relating to a wall.',[C('mural.s1','墙面壁画','The artists painted a mural of local river life across the school’s entrance wall.','艺术家们在学校入口墙面上画了一幅描绘当地河流生活的壁画。','The artists painted / a mural of local river life / across the school’s entrance wall.','mural.s1 作名词，指直接画在墙面上的大型绘画。','作品覆盖入口墙面。'),C('mural.s2','墙壁相关','The architect documented the building’s mural surfaces before the renovation team removed the damaged plaster.','建筑师在装修团队拆除受损灰泥前，记录了建筑的墙面区域。','The architect documented / the building’s mural surfaces / before the renovation team / removed the damaged plaster.','mural.s2 作形容词，表示与墙壁有关。','mural 修饰 surfaces，指墙面。')],M('The guide called the framed painting on a movable stand a mural although it was not painted on a wall.','The guide called the large painting executed directly on the entrance wall a mural.','摆在架上的画并非墙上绘制的壁画。'),[Q('Where was the artists’ mural painted?','Across the school entrance wall.','On a portable mug.','On a field of mud.','mural.s1 是墙面大型绘画。'),Q('Mural surfaces are?','surfaces relating to walls','surfaces of a movie screen only','the middle of a river','mural.s2 作形容词表示墙面的。'),Q('Mural derives from Latin murus meaning?','wall','music','mother','murus 意为墙。','word-formation'),Q('Which work is a mural?','A large painting made directly on a building wall.','A framed sketch on a desk.','A printed book cover','壁画直接绘制在墙上。')]);
P('murder','From Old English morðor and Proto-Germanic *murthra, “secret killing”; as a noun it is unlawful intentional killing, as a verb it means kill unlawfully and deliberately, and informally it can mean ruin something badly.',[C('murder.s1','刑事罪名','The jury considered whether the evidence proved murder, rather than an accidental death or a lesser offence.','陪审团考虑证据是否足以证明谋杀，而非意外死亡或较轻罪行。','The jury considered / whether the evidence proved murder / rather than an accidental death / or a lesser offence.','murder.s1 作名词指故意且非法杀人的罪行。','例句将其与意外死亡区分。'),C('murder.s2','非法杀害','The novel reveals that the villain murdered the witness to prevent her from testifying.','小说揭示反派为阻止证人作证而杀害了她。','The novel reveals / that the villain murdered the witness / to prevent her / from testifying.','murder.s2 作动词，指故意非法杀害某人。','行为目的是阻止证人出庭。'),C('murder.s3','口语糟蹋','The overcooked sauce murdered the delicate flavour of the fresh herbs, according to the chef.','厨师说，过度烹煮的酱汁把新鲜香草的细腻风味彻底毁了。','The overcooked sauce murdered / the delicate flavour / of the fresh herbs / according to the chef.','murder.s3 口语比喻指把作品、味道等严重糟蹋。','酱汁破坏了原有风味。')],M('The court charged him with murder after proving that the death was accidental, lawful, and entirely unintended.','The court charged him with murder after evidence showed he deliberately and unlawfully killed the victim.','意外、合法且非故意的死亡不符合谋杀定义。'),[Q('What did the jury assess?','Whether evidence proved unlawful intentional killing.','Whether a sauce contained mustard.','Whether the witness moved to another city.','murder.s1 指谋杀罪。'),Q('Why did the villain murder the witness?','To stop her from testifying.','To hire her as a musician.','To help her move forward.','murder.s2 指故意杀害。'),Q('The sauce murdered the herb flavour means it?','ruined the flavour badly','legally killed a person','preserved every fresh note','murder.s3 是口语比喻义。'),Q('Which two elements are central to the legal sense described?','Intentional and unlawful killing.','A noisy argument and a broken mug.','A move to another town.','定义强调故意且非法。','usage')]);
P('murky','Possibly related to a Scandinavian word for darkness; it means dark and difficult to see through, or unclear and suspicious.',C('murky.s1','浑浊水体','The divers avoided the murky canal because they could not see the submerged debris below the surface.','潜水员避开了浑浊的运河，因为他们看不清水面下的碎片。','The divers avoided / the murky canal / because they could not see / the submerged debris below the surface.','murky 可指昏暗、浑浊而难以看清，也可比喻不透明或可疑。','水体不清使潜水有危险。'),M('The divers entered the murky canal because it was crystal clear and every object beneath the water was visible.','The divers avoided the murky canal because they could not see underwater obstacles.','清澈见底与 murky 的浑浊义相反。'),[Q('Why did the divers avoid the canal?','It was murky and hid underwater debris.','It was clear and empty.','It was a multistory building.','murky 指浑浊难以看清。'),Q('A murky business deal may be?','unclear or suspicious','open and fully documented','a type of wall painting','murky 可比喻不透明、可疑。'),Q('What could the divers not see?','Debris below the surface.','The canal’s name on a map.','A movie playing nearby.','浑水遮住水下碎片。'),Q('Which word is closest to murky?','cloudy','transparent','multifunctional','cloudy 可形容水体浑浊。')]);
P('murmur','From Old French murmure and Latin murmurare, “to murmur”; the repeated sound is probably imitative. It can mean speak softly, complain quietly, or make a low continuous sound.',[C('murmur.s1','低声说话','She murmured a brief thank-you to the nurse so she would not wake the patient in the next bed.','她低声向护士道谢，以免吵醒隔壁床的病人。','She murmured a brief thank-you / to the nurse / so she would not wake / the patient in the next bed.','murmur.s1 作动词，指轻声、低语地说。','她压低声音表达感谢。'),C('murmur.s2','小声抱怨','A few passengers murmured about the delay, but most waited calmly for the revised departure time.','几名乘客小声抱怨延误，不过大多数人平静等待更新后的出发时间。','A few passengers murmured / about the delay / but most waited calmly / for the revised departure time.','murmur.s2 可指低声、不公开地抱怨。','乘客低声表达不满。'),C('murmur.s3','连续低响','A soft murmur of conversation filled the gallery while visitors studied the paintings.','游客欣赏画作时，展厅里充满轻柔的交谈声。','A soft murmur of conversation / filled the gallery / while visitors studied / the paintings.','murmur.s3 作名词可指连续、柔和的低声响或低语声。','交谈声持续而轻柔。')],M('The passenger murmured about the delay by shouting an angry complaint through a loudspeaker.','The passenger murmured quietly about the delay to the person beside him.','通过扩音器大声喊叫不是低声抱怨。'),[Q('Why did she murmur her thanks?','She did not want to wake the patient nearby.','She wanted everyone in the gallery to hear.','She was announcing a new departure time.','murmur.s1 指轻声说。'),Q('What did passengers murmur about?','The delay.','A new museum mural.','The nurse’s musical instrument.','murmur.s2 表示低声抱怨延误。'),Q('A soft murmur filled the gallery means there was?','a low continuous sound of conversation','complete silence','a loud alarm','murmur.s3 指柔和的低语声。'),Q('Which phrase is natural?','murmur a few words','murmur loudly through a megaphone','murmur the sound into a wall','murmur 常与低声说话搭配。','collocation')]);
P('muscle','From Latin musculus, literally “little mouse,” because some muscles were thought to resemble mice in shape or movement; it can mean body tissue, strength or influence, or force one’s way into something.',[C('muscle.s1','身体组织','The physiotherapist asked Daniel to tense the muscle in his calf and then relax it slowly.','理疗师让丹尼尔绷紧小腿肌肉，再慢慢放松。','The physiotherapist asked Daniel / to tense the muscle in his calf / and then relax it / slowly.','muscle.s1 指收缩以带动身体或器官活动的组织。','小腿肌肉在练习中收缩和放松。'),C('muscle.s2','力量影响力','The small union lacked the political muscle to change the law on its own.','这个小型工会缺乏单独改变法律所需的政治影响力。','The small union lacked / the political muscle / to change the law / on its own.','muscle.s2 可比喻身体力量或施加影响的能力。','政治影响力用 muscle 比喻力量。'),C('muscle.s3','强行介入','The larger firm muscled into the market by undercutting prices and buying the smaller supplier.','大公司通过压低价格并收购小供应商，强势挤入了市场。','The larger firm muscled into the market / by undercutting prices / and buying the smaller supplier.','muscle.s3 作动词常与 into 连用，指靠力量或影响强行进入。','公司用经济实力挤入市场。')],M('The firm muscled into the market by avoiding competition and deciding not to enter it.','The firm muscled into the market by using its financial power to displace smaller rivals.','没有进入市场就谈不上强行挤入。'),[Q('What did Daniel tense and relax?','A muscle in his calf.','A museum gallery.','A bowl of mustard.','muscle.s1 指身体肌肉组织。'),Q('Political muscle means?','influence or power','a calf tissue only','a musical instrument','muscle.s2 比喻政治力量。'),Q('How did the firm muscle into the market?','It used its economic power against smaller rivals.','It refused to enter the market.','It opened a public museum.','muscle.s3 表示强势进入。'),Q('The Latin word musculus literally meant?','little mouse','large city','quiet sound','该词源字面意为“小老鼠”。','word-formation')]);
P('muscular','From muscle plus -ar; it means having strong, well-developed muscles or relating to muscles in the body.',[C('muscular.s1','体格强健','The muscular rower lifted the boat onto the trailer without help from the rest of the crew.','这位肌肉发达的赛艇运动员独自把船抬上拖车，没有其他队员帮忙。','The muscular rower lifted the boat / onto the trailer / without help / from the rest of the crew.','muscular.s1 描写肌肉发达、强壮的人或动物。','运动员有足够力量独自抬船。'),C('muscular.s2','肌肉相关','The scan showed a small muscular injury near the shoulder, so the athlete rested before training again.','扫描显示肩部附近有轻微肌肉损伤，因此运动员休息后才恢复训练。','The scan showed / a small muscular injury / near the shoulder / so the athlete rested before training again.','muscular.s2 表示与肌肉有关的。','injury 涉及肩部肌肉。')],M('The report described the muscular injury as unrelated to muscles and located it only in the athlete’s shoe.','The report described the muscular injury as damage to tissue near the shoulder muscles.','鞋子损坏不是肌肉损伤。'),[Q('Why could the rower lift the boat alone?','He was muscular and strong.','The boat was made of paper.','The crew had moved away.','muscular.s1 指肌肉发达、强壮。'),Q('A muscular injury affects?','muscle tissue','a movie screen','a municipal budget','muscular.s2 表示与肌肉相关。'),Q('Which word means “having strong muscles”?','muscular','mucous','mundane','muscular 描写肌肉强健。'),Q('Muscular is formed from muscle plus?','-ar','-ment','-less','-ar 构成形容词 muscular。','word-formation')]);
P('muscularly','From muscular plus the adverb suffix -ly; it means in a muscular or physically strong way, or with respect to muscles.',C('muscularly.s1','肌肉用力','The climber muscularly hauled herself over the ledge, using her arms and shoulders to reach the safer shelf.','攀登者用手臂和肩部肌肉发力，把自己拉过岩沿，抵达更安全的平台。','The climber muscularly hauled herself / over the ledge / using her arms and shoulders / to reach the safer shelf.','muscularly 作副词，描述通过肌肉力量或从肌肉方面进行。','动作依靠上肢肌肉发力。'),M('The climber muscularly lifted the heavy crate without using any muscles or physical force.','The climber muscularly hauled herself over the ledge with arm and shoulder strength.','muscularly 表示以肌肉力量完成动作，不能同时说完全未用肌肉。'),[Q('How did the climber get over the ledge?','She pulled herself up with arm and shoulder strength.','She floated without touching the rock.','She moved the ledge away with a phone.','muscularly 描述肌肉发力。'),Q('Muscularly is an?','adverb','noun meaning a muscle','adjective meaning full of mud','muscularly 以 -ly 结尾作副词。'),Q('Which word is the base of muscularly?','muscular','museum','murmur','muscularly 由 muscular 加 -ly 构成。','word-formation'),Q('Which sentence uses muscularly naturally?','He pulled the stuck drawer muscularly with both arms.','He muscularly was a strong his legs.','The muscularly of the shoulder was painful.','muscularly 修饰用力拉抽屉的动作。','grammar')]);
P('muse','From Old French muser, “to ponder or stare,” ultimately of uncertain origin; as a verb it means to think deeply and quietly.',C('muse.s1','静思计划','She mused on the offer for several days before deciding whether to leave her secure job.','她对这份工作机会沉思了几天，才决定是否离开稳定的工作。','She mused on the offer / for several days / before deciding / whether to leave her secure job.','muse 常作不及物动词，表示安静、深入地思考，常接 on 或 about。','她反复思考是否接受机会。'),M('She mused on the offer by refusing to think about it and accepting immediately without consideration.','She mused on the offer before making a careful decision.','立即决定且不作考虑不符合沉思。'),[Q('What did she muse on?','Whether to accept the job offer.','How to repair a broken mussel shell.','Which musical note to play','muse on 指沉思某事。'),Q('To muse is to?','think deeply and quietly','speak loudly without thinking','move a building to another town','muse 表示沉思。'),Q('Which preposition naturally follows muse here?','on','at to','from with','常说 muse on an idea。','collocation'),Q('What did she do before deciding?','Thought about the offer for several days.','Sent an acceptance immediately.','Mowed the office lawn.','她先花数日思考。')]);
P('museum','From Latin museum and Greek mouseion, “seat or temple of the Muses”; it names a public institution where objects of art, history, or science are displayed.',C('museum.s1','公共展馆','The city museum opened a new science gallery where visitors can handle safe models of ancient machines.','市立博物馆开放了新的科学展厅，游客可以操作古代机器的安全模型。','The city museum opened / a new science gallery / where visitors can handle / safe models of ancient machines.','museum 指收藏并向公众展示艺术、历史或科学物品的机构。','科学展厅展出历史机器模型。'),M('The guide called the locked private cupboard a museum even though it held no collection and admitted no visitors.','The guide called the public building a museum because it displayed historical and scientific objects.','既无藏品也不对公众开放的柜子不符合博物馆定义。'),[Q('What opened at the city museum?','A science gallery.','A new municipal courthouse.','A mudflat walkway.','museum 是收藏展示场所。'),Q('What may visitors see in a museum?','Objects related to art, history, or science.','Only private bills and receipts.','Only living mice.','博物馆展示多类文化或科学物品。'),Q('Museum is historically linked with Greek mouseion, a place of?','the Muses','mussels','murder cases','mouseion 与缪斯及艺术学问相关。','word-formation'),Q('Which institution is a museum?','A public building displaying historical objects.','A private cupboard with no collection.','A phone repair shop','博物馆向公众展示藏品。')]);
P('mushroom','From Anglo-French musherun or Old French meisseron, of uncertain deeper origin; it names a fungus, and as a verb means grow or spread rapidly.',[C('mushroom.s1','菌类食物','The chef sliced a fresh mushroom into the soup after checking that it came from a safe, identified variety.','厨师确认这种新鲜蘑菇品种安全后，把它切片放进汤里。','The chef sliced / a fresh mushroom into the soup / after checking / that it came from a safe, identified variety.','mushroom.s1 指一种有菌盖和菌柄的真菌，部分品种可食用。','厨师先确认品种安全再烹饪。'),C('mushroom.s2','快速增长','Unlicensed delivery services mushroomed across the city after a new app made it easy to recruit drivers.','一款新应用让招募司机变得容易后，未经许可的配送服务在全城迅速涌现。','Unlicensed delivery services mushroomed / across the city / after a new app / made it easy to recruit drivers.','mushroom.s2 作动词，表示数量或规模快速增长、涌现。','服务商数量迅速增加。')],M('The company said the number of services mushroomed, but explained that it had fallen from fifty to one.','The company said delivery services mushroomed after the app made recruitment easier.','从五十家降至一家不是快速增长。'),[Q('What did the chef add to the soup?','A fresh fungus after checking its variety.','A piece of mudstone.','A whole museum label.','mushroom.s1 指可食用菌类。'),Q('What happened to delivery services after the app launched?','They grew rapidly in number.','They all closed immediately.','They became a type of fungus.','mushroom.s2 表示迅速增长。'),Q('A mushroom is generally a?','fungus with a cap and stem','multistory building','musical notation','蘑菇是菌类。'),Q('Which phrase uses mushroom as a verb?','New cafés mushroomed along the street.','She sliced a mushroom for soup.','The mushroom was fresh.','mushroomed 表示迅速涌现。','grammar')]);
P('music','From Greek mousikē (technē), “the art of the Muses,” through Latin musica and Old French musique; it can mean organised sound or written musical notation.',[C('music.s1','声音艺术','The quiet music helped the children focus while they drew pictures in the library’s activity room.','轻柔的音乐帮助孩子们在图书馆活动室里专心画画。','The quiet music helped the children focus / while they drew pictures / in the library’s activity room.','music.s1 指有节奏、旋律等组织起来的人声或器乐声音。','乐曲帮助孩子集中注意力。'),C('music.s2','乐谱符号','The violinist read the music carefully and marked the bars where the tempo changed.','小提琴手仔细阅读乐谱，并标出速度变化的小节。','The violinist read the music / carefully / and marked the bars / where the tempo changed.','music.s2 可指记录音高和节奏的乐谱。','演奏者阅读小节和速度标记。')],M('The violinist read the music without any written notes, bars, or signs on the page.','The violinist read the written music and followed its tempo markings.','没有任何书写符号的页面不是乐谱。'),[Q('What helped the children focus?','Quiet organised sound.','A silent mural.','A muddy path.','music.s1 指音乐声音。'),Q('What did the violinist read?','Written notes and tempo markings.','A municipal budget.','A museum visitor’s face','music.s2 指乐谱。'),Q('Music is historically related to Greek mousikē, the art of?','the Muses','mice','mussels','古希腊 mousikē 指缪斯的艺术。','word-formation'),Q('Which phrase uses music to mean notation?','The musician studied the music before rehearsal.','She listened to music while driving.','The music sounded soft.','studied the music 在此指阅读乐谱。')]);
P('musical','From music plus -al; it means relating to music, and a musical is a play or film that uses songs and music as a central feature.',[C('musical.s1','音乐相关','The school hired a musical director to coach the choir and coordinate the orchestra for the spring performance.','学校聘请了一位音乐总监，为合唱团辅导并协调春季演出的管弦乐队。','The school hired / a musical director / to coach the choir / and coordinate the orchestra for the spring performance.','musical.s1 作形容词，表示与音乐有关。','director 负责合唱和管弦乐团。'),C('musical.s1','歌舞剧作品','The family watched a musical about a young composer whose songs help reunite a divided neighbourhood.','一家人观看了一部音乐剧，讲述年轻作曲家用歌曲让分裂的社区重新团结。','The family watched / a musical / about a young composer / whose songs help reunite a divided neighbourhood.','musical 也可作名词，指以歌曲和音乐为重要组成部分的舞台剧或电影。','作品通过歌曲推进故事。')],M('The theatre advertised a musical, but the production contained no songs, music, or musical performance.','The theatre advertised a musical that used songs to tell the composer’s story.','完全没有音乐或歌曲的作品不符合音乐剧义。'),[Q('What did the musical director coordinate?','The choir and orchestra.','The museum’s fossil collection.','The municipal water pipes.','musical.s1 表示与音乐有关。'),Q('What kind of production did the family watch?','A play or film using songs centrally.','A silent legal report.','A multivolume dictionary','musical 作名词指音乐剧。'),Q('Which phrase uses musical as an adjective?','musical director','a musical opened last night','watch a musical','musical director 中 musical 修饰名词。','grammar'),Q('Which phrase uses musical as a noun?','They attended a musical.','She bought a musical instrument.','The musical score was printed.','a musical 作名词指音乐剧。','grammar')]);
P('musical instrument','A compound of musical and instrument; it names a device made or adapted for producing music.',C('musical instrument.s1','乐器演奏','The museum lets visitors try a simple musical instrument made from bamboo tubes and a wooden frame.','博物馆允许游客试奏一种由竹管和木框制成的简易乐器。','The museum lets visitors try / a simple musical instrument / made from bamboo tubes / and a wooden frame.','musical instrument 指用于演奏或产生音乐的器具。','竹管和木框构成可演奏器具。'),M('The catalogue listed a silent empty storage box as a musical instrument, although it could not produce any sound.','The catalogue listed the bamboo flute as a musical instrument because it produced pitched notes.','不能发声的空箱不是乐器。'),[Q('What could visitors try?','A bamboo musical instrument.','A municipal water pipe.','A ceramic mug.','musical instrument 指能演奏音乐的器具。'),Q('What materials made the instrument?','Bamboo tubes and a wooden frame.','Mud and a stone.','Mussel shells and wool.','例句列出竹管和木框。'),Q('Which item is a musical instrument?','A violin.','A printed map.','A movie ticket.','小提琴用于演奏音乐。'),Q('Musical instrument is a compound of musical and?','instrument','mural','murmur','该词由 musical 和 instrument 构成。','word-formation')]);
P('musician','From music plus -ian; it means a person skilled in performing or composing music.',C('musician.s1','音乐演奏者','The musician practised the difficult passage slowly before performing it with the orchestra.','这位音乐家在与管弦乐队合奏前，先慢慢练习了那段难曲。','The musician practised / the difficult passage slowly / before performing it / with the orchestra.','musician 指演奏、创作或以音乐为职业的人。','演奏者练习并与乐团合奏。'),M('The biography called the musician a composer although she had never written music or played an instrument.','The biography called the trained violin performer a musician.','一生从未演奏或创作音乐的人不符合此处称谓。'),[Q('What did the musician practise?','A difficult musical passage.','A municipal tax form.','A muddy walking route.','musician 指从事或擅长音乐的人。'),Q('Who performed the passage?','The musician with an orchestra.','A museum curator alone.','A delivery driver in a car park.','例句说她与管弦乐队演奏。'),Q('A musician may?','perform or compose music','only repair walls','only collect mussels','音乐家可以演奏或创作音乐。'),Q('Which suffix forms musician from music?','-ian','-less','-ful','-ian 表示从事某领域的人。','word-formation')]);
P('musicologist','Formed from music plus -ologist, a person who studies a subject; it means a scholar of music’s history, structure, and cultural context.',C('musicologist.s1','音乐学研究','The musicologist compared handwritten scores to learn how the composer revised the final movement.','音乐学者比较手写乐谱，以研究作曲家如何修改最后一个乐章。','The musicologist compared handwritten scores / to learn / how the composer revised / the final movement.','musicologist 指研究音乐史、结构或文化背景的学者。','研究者通过比较乐谱分析创作过程。'),M('The article called a chef who never studied music a musicologist because she prepared soup in a restaurant.','The article called the scholar who analysed scores and musical history a musicologist.','烹饪工作与音乐研究无关。'),[Q('What did the musicologist compare?','Handwritten scores.','Mustard seeds.','Museum floor plans.','musicologist 研究音乐及其材料。'),Q('What question was the scholar investigating?','How the composer revised the final movement.','How to grow a mulberry tree.','Why a train arrived late.','比较乐谱是为了研究修订过程。'),Q('A musicologist is a scholar of?','music','mud','municipal law','musicologist 指音乐学者。'),Q('Which suffix means a specialist or scholar?','-ologist','-muff','-ish','-ologist 表示研究者或专家。','word-formation')]);
P('musket','From French mousquet, likely through Italian moschetto; it was a heavy shoulder-fired gun used especially from the sixteenth to nineteenth centuries.',C('musket.s1','历史火枪','The museum’s musket had a long barrel and a wooden stock, and its label explained that it required slow loading.','博物馆里的火枪有长枪管和木托，说明牌解释它需要缓慢装填。','The museum’s musket had / a long barrel and a wooden stock / and its label explained / that it required slow loading.','musket 指历史上较重、肩扛发射的火枪。','枪管、枪托和装填方式与历史火枪相符。'),M('The curator labelled the lightweight modern laser pointer a musket, though it had no barrel, stock, or ammunition.','The curator labelled the old shoulder-fired gun a musket.','没有枪管或弹药的激光笔不是火枪。'),[Q('What features did the museum musket have?','A long barrel and wooden stock.','A computer screen and wireless mouse.','A ceramic handle and tea leaves.','musket 是历史枪械，通常有枪管和枪托。'),Q('What did the label say about loading?','It was slow.','It happened automatically every second.','The weapon used no ammunition.','历史火枪需要较慢装填。'),Q('A musket is a type of?','historical firearm','musical instrument','mushroom','musket 指火枪。'),Q('Which period is associated with muskets in the source?','The sixteenth to nineteenth centuries.','The twenty-first century only.','Ancient prehistory only.','火枪主要在16至19世纪使用。')]);
P('mussel','From Old English muscle or musscel through Late Latin muscula; the modern spelling was later distinguished from muscle. It is an edible bivalve mollusc.',C('mussel.s1','双壳贝类','The cook discarded every mussel whose shell stayed open after tapping it, following the food-safety guidance.','厨师按食品安全指引，丢弃了敲击后仍保持张开的贻贝。','The cook discarded / every mussel whose shell stayed open / after tapping it / following the food-safety guidance.','mussel 指可食用的双壳软体动物，如海产贻贝。','例句指一种需检查鲜度的贝类。'),M('The menu called the shelled mammal a mussel even though it breathed air and had fur.','The menu listed mussels as edible bivalve shellfish.','有毛并用肺呼吸的哺乳动物不是双壳贝。'),[Q('What did the cook discard?','Mussels with shells that stayed open after tapping.','A muscular shoulder.','A museum ticket.','mussel 指贻贝等双壳贝类。'),Q('A mussel is a?','bivalve mollusc','large land mammal','musical scale','mussel 属双壳软体动物。'),Q('Why did the cook check the shells?','To follow food-safety guidance.','To count the city’s floors.','To identify a movie genre.','贝类新鲜度需按指引检查。'),Q('Mussel is spelled differently from?','muscle','mural','mutter','现代拼写用 mussel 区分 muscle。','spelling')]);
P('must','From Old English moste, the past tense of motan, “have to”; the modal means obligation or strong inference, and the noun can mean something essential or highly desirable.',[C('must.s1','义务要求','Passengers must keep the emergency aisle clear during the flight.','乘客在飞行期间必须保持紧急通道畅通。','Passengers must keep / the emergency aisle clear / during the flight.','must.s1 作情态动词，表示必须履行的义务或要求。','航空安全规定要求通道保持畅通。'),C('must.s2','根据证据推断','The porch light is on and both cars are here, so the family must be at home.','门廊灯亮着，两辆车也都在，所以家人一定在家。','The porch light is on / and both cars are here / so the family must be at home.','must.s2 可表示根据证据作出的肯定推断。','灯和汽车提供了推断依据。'),C('must.s3','必看之物','For anyone interested in local history, the restored harbour museum is a must.','对当地历史感兴趣的人来说，修复后的港口博物馆是必去之处。','For anyone interested in local history / the restored harbour museum / is a must.','must.s3 作名词指非常值得做、看或体验的事物。','语境将博物馆推荐为必看景点。')],M('Passengers must keep the aisle clear by stacking bags across it and blocking the exit.','Passengers must keep the aisle clear by stowing bags in the overhead compartment.','堵塞紧急通道违反了 must 表示的规定要求。'),[Q('What must passengers do?','Keep the emergency aisle clear.','Place bags across the exit.','Leave the aircraft in flight.','must.s1 表示规定义务。'),Q('Why must the family be at home?','The porch light is on and both cars are present.','The house has no lights or vehicles.','A musician called them.','must.s2 表示根据证据推断。'),Q('The harbour museum is a must means it is?','something highly recommended to visit','a legal requirement for every traveller','a type of musical instrument','must.s3 指值得做或看的事。'),Q('Which sentence expresses strong inference?','The ground is wet; it must have rained.','You must wear a helmet under the rule.','The museum is a must-see.','地面湿是“肯定下过雨”的证据推断。')]);
P('must give','A phrase combining the modal must with give; it expresses an obligation to hand, provide, or return something.',C('must give.s1','必须交还','You must give the library book back by Friday so another student can borrow it next week.','你必须在周五前把图书馆的书还回去，这样另一名学生下周才能借。','You must give the library book back / by Friday / so another student / can borrow it next week.','must give 表示有义务给予或交还；具体含义由 give 后的宾语和小品词决定。','must 表义务，give back 表示归还图书。'),M('You must give the borrowed book back by keeping it permanently and refusing to return it.','You must give the borrowed book back to the library by Friday.','永久留下书与交还义务直接冲突。'),[Q('What must the borrower do by Friday?','Return the book to the library.','Buy a new museum.','Keep the book forever.','must give back 表示必须归还。'),Q('In “must give the food to the guests,” must expresses?','an obligation','a past event','a question about ability','must 表示必须履行的义务。'),Q('What does give back mean?','return something to its owner','take something without permission','make a musical sound','give back 表示归还。'),Q('Which sentence uses must give naturally?','You must give the form to the clerk today.','You must gives the form to the clerk.','You must giving the form today.','情态动词 must 后接动词原形 give。','grammar')]);
P('mustard','From Old French mostarde, related to must, “new wine,” because the condiment was originally mixed with grape must and ground seeds; it also names the plant.',[C('mustard.s1','调味酱料','She spread a little mustard on the sandwich and tasted it before adding more.','她在三明治上抹了一点芥末酱，尝过后才决定是否再加。','She spread / a little mustard on the sandwich / and tasted it / before adding more.','mustard.s1 指用芥菜籽制成的黄色辛辣调味酱。','抹在三明治上的是调味品。'),C('mustard.s2','开花植物','The field turned bright yellow when the mustard plants bloomed along the road in spring.','春天路边的芥菜开花时，整片田野变成了明亮的黄色。','The field turned bright yellow / when the mustard plants bloomed / along the road / in spring.','mustard.s2 也指开黄花、种子可制调味品的植物。','例句中的作物正在开花。')],M('The sandwich recipe calls for mustard plants as a yellow sauce spread directly on the bread without processing seeds.','The recipe calls for mustard, the prepared spicy condiment made from ground seeds.','植株不是可以直接抹在面包上的加工酱料。'),[Q('What did she spread on the sandwich?','A spicy condiment made from mustard seeds.','A whole flowering shrub.','A bowl of mud.','mustard.s1 指调味酱。'),Q('What colour were the flowering fields?','Bright yellow.','Deep blue.','Transparent','芥菜开花时呈黄色。'),Q('Mustard can refer to?','the condiment or the plant','only a musical note','a city government','该词可指调味品或芥菜植物。'),Q('Why was the condiment historically called mustard?','It was mixed with grape must and ground seeds.','It was first served in a museum.','It was made from mushrooms only.','mostarde 与 must 有历史关联。','word-formation')]);
P('muster','From Old French mostrer and Latin monstrare, “to show”; it means gather people together, or gather up qualities such as courage.',C('muster.s1','召集队伍','The captain mustered the rescue crew at dawn and assigned each person a radio and a route.','队长黎明时召集救援队，并为每个人分配一台无线电和一条路线。','The captain mustered the rescue crew / at dawn / and assigned each person / a radio and a route.','muster 可指召集人群或军队集合，也可比喻鼓起勇气等。','队伍集合后接受任务分配。'),M('The captain mustered the crew by scattering every member across the city without contacting them.','The captain mustered the crew at the station and assigned their rescue tasks.','让人员分散且不联系，不是集合队伍。'),[Q('When did the captain muster the rescue crew?','At dawn.','At midnight after everyone went home.','After the rescue was cancelled.','muster 指召集集合。'),Q('What did each crew member receive?','A radio and a route.','A musical score and a mussel.','A museum membership.','队员收到通信设备和路线。'),Q('To muster courage means to?','summon or gather courage','lose all confidence deliberately','measure courage in millimetres','muster up courage 表示鼓起勇气。'),Q('Which phrase is standard?','muster a team','muster to a team up','muster a team into courage of','muster 可直接接被召集的人群。','collocation')]);
P('mutate','From Latin mutare, “to change”; it can mean that an organism or thing changes form, or that something causes a genetic change.',[C('mutate.s1','自然变异','The virus can mutate over time, which is why researchers continue to monitor changes in its genetic sequence.','病毒会随时间发生变异，因此研究人员持续监测其基因序列变化。','The virus can mutate / over time / which is why researchers continue / to monitor changes in its genetic sequence.','mutate.s1 作不及物动词，指自身发生遗传或形态变化。','病毒序列随时间变化。'),C('mutate.s2','诱发突变','In the laboratory, the treatment mutated the cells by altering a specific section of their DNA.','在实验室里，这种处理改变了细胞DNA的特定片段，使细胞发生变异。','In the laboratory / the treatment mutated the cells / by altering / a specific section of their DNA.','mutate.s2 作及物动词，指使生物体发生遗传改变。','处理造成细胞DNA变化。')],M('The virus mutated in the experiment, but researchers confirmed that its genetic sequence had remained completely unchanged.','The virus mutated in the experiment, and researchers recorded changes in its genetic sequence.','序列完全未变就不支持发生变异。'),[Q('What can happen to the virus over time?','Its genetic sequence can change.','It must become a museum.','It can grow a moustache.','mutate.s1 指自身发生变化。'),Q('What did the laboratory treatment do to the cells?','Altered a section of their DNA.','Recorded a movie.','Removed every cell from the sample.','mutate.s2 指使细胞发生遗传改变。'),Q('To mutate can mean?','change in form or genetic sequence','return an item to a library','gather a rescue team','mutate 表示发生或造成变化。'),Q('Which use makes mutate transitive?','The chemical mutated the cells.','The virus mutated rapidly.','The species mutated over centuries.','及物用法后接被改变的对象。','grammar')]);
P('mutation','From Latin mutatio, “a changing,” from mutare, “to change”; it means a genetic change or, more broadly, a change into a new form.',[C('mutation.s1','基因变化','The study found a mutation in one gene that changed how the plant resisted a common disease.','研究发现一个基因发生突变，改变了植物抵抗常见疾病的能力。','The study found / a mutation in one gene / that changed / how the plant resisted a common disease.','mutation.s1 指生物基因发生的改变。','特定基因的变化影响抗病性。'),C('mutation.s2','形态转变','The artist’s latest design is a mutation of the earlier pattern, retaining its outline while changing its colours and scale.','艺术家最新的设计是早期图案的变体，保留轮廓但改变了颜色和比例。','The artist’s latest design / is a mutation of the earlier pattern / retaining its outline / while changing its colours and scale.','mutation.s2 可泛指变成新形式的变化或结果。','新设计由旧图案改造而来。')],M('The report called the plant’s genetic mutation a mutation, then stated that no gene or trait had changed.','The report identified a mutation in the gene that altered the plant’s disease resistance.','基因和性状都未改变时，不应称为遗传突变。'),[Q('What did the mutation affect in the plant study?','How the plant resisted a disease.','The colour of a museum wall.','The number of rows in a theater.','mutation.s1 指基因变化并影响性状。'),Q('The new design is a mutation of the earlier pattern means it?','changed into a new form while retaining some features','is exactly identical in every detail','was never based on the earlier design','mutation.s2 指形式变化。'),Q('Mutation comes from a Latin word meaning?','a changing','a little mouse','a public gathering','mutatio 意为变化。','word-formation'),Q('A mutation may refer to?','a genetic change or a broader transformation','only a kind of mushroom','a person’s title','mutation 有遗传义和泛指变化义。')]);

})();
